INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-01-history-civilization', 'history-and-civilization', 'تاريخ عُمان وحضارتها', 'العمق الحضاري لعُمان منذ حضارة مجان وتجارة النحاس واللبان والمواقع الأثرية المدرجة في التراث العالمي.', 'Landmark', 1, '["حضارة مجان والنحاس","مواقع الألف الثالث قبل الميلاد","العصر الإسلامي المبكر","المدن والموانئ التاريخية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-02-governorates', 'governorates-and-wilayats', 'المحافظات والولايات والقرى', 'التقسيم الإداري لسلطنة عُمان الذي يضم 11 محافظة و63 ولاية وما يتبعها من نيابات وقرى عريقة.', 'MapPin', 2, '["محافظة مسقط","محافظة ظفار","محافظة مسندم","محافظة الداخلية","محافظتا شمال وجنوب الباطنة","محافظتا شمال وجنوب الشرقية","محافظات البريمي والظاهرة والوسطى"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-03-geography', 'geography-mountains-wadis-deserts', 'الجغرافيا والجبال والأودية والصحاري', 'التنوع التضاريسي الفريد لسلطنة عُمان من سلسلة جبال الحجر والجبل الأخضر إلى الأودية والكهوف والصحاري.', 'Mountain', 3, '["سلسلة جبال الحجر والجبل الأخضر","جبال ظفار","الأودية والعيون المائية","رمال الشرقية والربع الخالي","الكهوف والظواهر الجيولوجية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-04-seas-islands', 'seas-islands-and-coasts', 'البحار والجزر والسواحل', 'الشريط الساحلي الممتد لأكثر من 3,165 كم على بحر عُمان وبحر العرب والمحيط الهندي والجزر العُمانية الاستراتيجية.', 'Compass', 4, '["جزيرة مصيرة","محمية جزر الديمانيات","جزر الحلانيات","مضيق هرمز والأخوار البحرية","تاريخ الملاحة البحرية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-05-castles-forts', 'castles-forts-and-monuments', 'القلاع والحصون والمعالم التاريخية', 'العمارة الدفاعية والمدنية العُمانية المتمثلة في القلاع والحصون والأبراج والأسوار التاريخية الشامخة.', 'Shield', 5, '["القلاع المدرجة في اليونسكو","قلاع وحصون الداخلية","قلاع مسقط والباطنة","الأبراج والأسوار الدفاعية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-06-personalities', 'omani-personalities', 'الشخصيات العُمانية', 'تراجم وسير العلماء والملاحين والأدباء والمؤرخين والفقهاء العُمانيين الذين أسهموا في الحضارة الإنسانية.', 'Users', 6, '["علماء اللغة والأدب","رواد الملاحة والفلك","المؤرخون والفقهاء","الأطباء والعلماء الطبيعيون"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-07-sultans-rulers', 'sultans-rulers-and-historical-events', 'السلاطين والحكام والأحداث التاريخية', 'تاريخ الدولة البوسعيدية منذ تأسيسها عام 1744م والدول المتعاقبة والعهود النهضوية والأحداث المفصلية.', 'Crown', 7, '["الدولة البوسعيدية","عصر النهضة العُمانية والنهضة المتجددة","دولة اليعاربة","الإمامة في العصور الإسلامية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-08-heritage-traditions', 'heritage-customs-and-traditions', 'التراث والعادات والتقاليد', 'الموروث الثقافي غير المادي، وأنظمة الأفلاج العُمانية، والسبلة العُمانية، والسنع والأزياء التقليدية.', 'Sparkles', 8, '["أنظمة الري بالأفلاج","السبلة والضيافة العُمانية","الأزياء والحلي التقليدية","المناسبات والأعراف الاجتماعية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-09-arts-crafts', 'arts-music-and-traditional-crafts', 'الفنون والموسيقى والحرف التقليدية', 'الفنون الأدائية والشعبية كالرزحة والعازي، والصناعات الحرفية الأصيلة كصياغة الخنجر العُماني والفخار.', 'Palette', 9, '["الفنون الحماسية (الرزحة والعازي)","صناعة الخنجر والفضيات","صناعة الحلوى العُمانية","الفخار والنسيج والسعفيات"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-10-literature-poetry', 'literature-poetry-and-language', 'الأدب والشعر واللغة', 'مسيرة الأدب والشعر الفصيح والشعبي في عُمان، والدراسات المعجمية والعروضية واللهجات واللغات المحلية.', 'Feather', 10, '["المعاجم وعلم العروض","الشعر العُماني الفصيح","الشعر النبطي وفن الميدان","اللغات واللهجات المحلية في عُمان"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-11-science-education', 'science-and-education', 'العلوم والتعليم', 'المؤسسات الأكاديمية والجامعات والمراكز البحثية والإسهامات العلمية العُمانية قديماً وحديثاً.', 'GraduationCap', 11, '["التعليم العالي والجامعات","المخطوطات العلمية والطب التقليدي","المراكز البحثية والابتكار"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-12-economy-trade', 'economy-trade-and-industry', 'الاقتصاد والتجارة والصناعة', 'المقومات الاقتصادية والمناطق الاقتصادية الخاصة والموانئ اللوجستية والطاقة المتجددة والتجارة البحرية.', 'Briefcase', 12, '["المنطقة الاقتصادية الخاصة بالدقم","الموانئ والخدمات اللوجستية","الطاقة المتجددة والهيدروجين الأخضر","الاقتصاد الأزرق والثروة السمكية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-13-environment-wildlife', 'environment-and-wildlife', 'البيئة والحياة البرية', 'المحميات الطبيعية البرية والبحرية وجهود صون التنوع الأحيائي والنظم البيئية في سلطنة عُمان.', 'ShieldCheck', 13, '["المحميات الطبيعية البرية","المحميات البحرية والأخوار","حماية السلاحف البحرية","التشريعات والمبادرات البيئية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-14-flora-fauna', 'plants-and-animals', 'النباتات والحيوانات', 'الغطاء النباتي الفريد كأشجار اللبان والورد الجبلي، والكائنات الفطرية كالمها العربي والنمر العربي.', 'Sprout', 14, '["شجرة اللبان والنباتات العطرية","الثدييات البرية النادرة","الطيور المستوطنة والمهاجرة","الأحياء البحرية والشعاب المرجانية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-15-tourism-nature', 'tourism-and-natural-landmarks', 'السياحة والمعالم الطبيعية', 'المقومات السياحية الطبيعية والبيئية والتراثية، من خريف ظفار إلى سياحة المغامرات الجبلية والبحرية.', 'Sun', 15, '["موسم خريف ظفار","السياحة الجبلية والبيئية","العيون الحارة والأودية السياحية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-16-national-institutions', 'national-institutions-and-initiatives', 'المؤسسات والمبادرات الوطنية', 'الصروح الثقافية والمؤسسات الوطنية والمتاحف والمبادرات المعرفية والتنموية في سلطنة عُمان.', 'Building2', 16, '["المتاحف الوطنية والصروح الثقافية","المؤسسات البحثية والأرشيفية","المبادرات الوطنية والمجتمعية"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO categories (id, slug, name, description, icon, sort_order, subcategories) VALUES ('cat-17-modern-oman', 'modern-history-and-contemporary-oman', 'التاريخ الحديث وعُمان المعاصرة', 'مسيرة الدولة الحديثة، ومستهدفات رؤية عُمان 2040، واللامركزية الإدارية لتنمية المحافظات والتحول الرقمي.', 'Globe', 17, '["رؤية عُمان 2040","نظام المحافظات واللامركزية الإدارية","التحول الرقمي والتنمية المستدامة"]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO volumes (id, volume_number, slug, title, subtitle, description, letter_range, category_ids, cover_theme) VALUES ('vol-01', 1, 'volume-1-land-and-geography', 'المجلد الأول: الأرض والطبيعة والمحافظات العُمانية', 'الجغرافيا، المحافظات والولايات، البحار والجزر، والبيئة الفطرية', 'يستعرض هذا المجلد البنية الجغرافية والتضاريسية لسلطنة عُمان، والتقسيم الإداري للمحافظات الـ 11، والجزر الساحلية، والمحميات البيئية والكائنات الفطرية.', 'أ — ج', '["cat-02-governorates","cat-03-geography","cat-04-seas-islands","cat-13-environment-wildlife","cat-14-flora-fauna","cat-15-tourism-nature"]'::jsonb, 'green') ON CONFLICT (id) DO NOTHING;
INSERT INTO volumes (id, volume_number, slug, title, subtitle, description, letter_range, category_ids, cover_theme) VALUES ('vol-02', 2, 'volume-2-history-and-busaid-state', 'المجلد الثاني: التاريخ الحضاري والدولة البوسعيدية', 'من حضارة مجان القديمة إلى تأسيس الدولة البوسعيدية وعصر النهضة', 'يوثق هذا المجلد الحقب التاريخية الممتدة من الألف الثالث قبل الميلاد، ودور عُمان في التجارة البحرية، وتأسيس الدولة البوسعيدية عام 1744م.', 'ح — س', '["cat-01-history-civilization","cat-07-sultans-rulers"]'::jsonb, 'red') ON CONFLICT (id) DO NOTHING;
INSERT INTO volumes (id, volume_number, slug, title, subtitle, description, letter_range, category_ids, cover_theme) VALUES ('vol-03', 3, 'volume-3-castles-forts-and-world-heritage', 'المجلد الثالث: القلاع والحصون ومواقع التراث العالمي', 'العمارة الدفاعية العُمانية والأفلاج والمعالم المسجلة في اليونسكو', 'يرصد هذا المجلد القلاع والحصون التاريخية كقلعة بهلا وقلعة نزوى وحصن جبرين، وهندسة الأفلاج العُمانية الخمسة المدرجة في قائمة التراث العالمي.', 'ش — ق', '["cat-05-castles-forts","cat-08-heritage-traditions"]'::jsonb, 'gold') ON CONFLICT (id) DO NOTHING;
INSERT INTO volumes (id, volume_number, slug, title, subtitle, description, letter_range, category_ids, cover_theme) VALUES ('vol-04', 4, 'volume-4-scholars-literature-and-sciences', 'المجلد الرابع: الأعلام والعلماء والأدب والعلوم', 'الشخصيات العُمانية، اللغة والشعر، والمنارات الأكاديمية', 'يتناول سير أعلام عُمان في اللغة والملاحة والتاريخ كالخليل بن أحمد الفراهيدي وأحمد بن ماجد، وحركة التعليم والجامعات العُمانية.', 'ك — م', '["cat-06-personalities","cat-10-literature-poetry","cat-11-science-education"]'::jsonb, 'emerald') ON CONFLICT (id) DO NOTHING;
INSERT INTO volumes (id, volume_number, slug, title, subtitle, description, letter_range, category_ids, cover_theme) VALUES ('vol-05', 5, 'volume-5-arts-crafts-and-institutions', 'المجلد الخامس: الفنون والحرف والصروح الثقافية', 'الفنون الشعبية، الصناعات الحرفية، والمتاحف الوطنية', 'يغطي الفنون العُمانية الأصيلة كالرزحة والعازي، وصناعة الخنجر العُماني، ودور الصروح الوطنية كالمتحف الوطني العُماني.', 'ن — و', '["cat-09-arts-crafts","cat-16-national-institutions"]'::jsonb, 'crimson') ON CONFLICT (id) DO NOTHING;
INSERT INTO volumes (id, volume_number, slug, title, subtitle, description, letter_range, category_ids, cover_theme) VALUES ('vol-06', 6, 'volume-6-modern-oman-and-economy', 'المجلد السادس: عُمان المعاصرة والاقتصاد ورؤية 2040', 'التحول الاقتصادي، المنطقة الاقتصادية الخاصة بالدقم، ومستهدفات المستقبل', 'يركز على مسيرة النهضة المتجددة، ومرتكزات رؤية عُمان 2040، والمشاريع الاقتصادية الكبرى في الدقم والطاقة المتجددة.', 'هـ — ي', '["cat-12-economy-trade","cat-17-modern-oman"]'::jsonb, 'amber') ON CONFLICT (id) DO NOTHING;
