INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-01-busaid-state', 'al-busaid-state-and-modern-renaissance', 'الدولة البوسعيدية ومسيرة النهضة العُمانية الحديثة والمتجددة', 'الدوله البوسعيديه ومسيره النهضه العمانيه الحديثه والمتجدده', 'تأسست الدولة البوسعيدية في سلطنة عُمان عام 1744م على يد الإمام أحمد بن سعيد البوسعيدي، وشكلت ركيزة الوحدة الوطنية والسيادة البحرية وصولاً إلى عصر النهضة الحديثة والمتجددة.', 'تاسست الدوله البوسعيديه في سلطنه عمان عام 1744م علي يد الامام احمد بن سعيد البوسعيدي وشكلت ركيزه الوحده الوطنيه والسياده البحريه وصولا الي عصر النهضه الحديثه والمتجدده', 'تُمثل الدولة البوسعيدية المرحلة التاريخية والسياسية الممتدة في سلطنة عُمان منذ منتصف القرن الثامن عشر الميلادي وحتى العصر الحاضر. تأسست الدولة عام 1744م عندما بويع الإمام أحمد بن سعيد البوسعيدي (الذي كان والياً على صحار) إماماً لعُمان، بعد نجاحه في توحيد البلاد وإنهاء الانقسامات الداخلية وحماية السيادة الوطنية على السواحل العُمانية.

شهدت عُمان في عهد الدولة البوسعيدية تحولاً استراتيجياً كبيراً؛ إذ عززت مكانتها البحرية والتجارية في المحيط الهندي وبحر العرب وشرق أفريقيا، وازدهرت الموانئ العُمانية مثل مسقط وصحار وصور بوصفها مراكز للتبادل التجاري والدبلوماسي الدولي. وفي عهد السيد سعيد بن سلطان البوسعيدي (1806–1856م) بلغت العلاقات الدولية والتجارية ذروتها، حيث أقامت عُمان علاقات دبلوماسية ومعاهدات تجارية موثقة مع قوى عالمية كالولايات المتحدة الأمريكية عام 1833م وبريطانيا وفرنسا.

وفي العصر الحديث، انطلقت مسيرة النهضة العُمانية الحديثة في 23 يوليو 1970م بقيادة السلطان الراحل قابوس بن سعيد بن تيمور — طيب الله ثراه — الذي أرسى دعائم دولة المؤسسات والقانون، وبنى البنية الأساسية الشاملة في التعليم والصحة والاقتصاد والعلاقات الخارجية المتوازنة القائمة على السلام وحسن الجوار.

ومنذ 11 يناير 2020م، يقود حضرة صاحب الجلالة السلطان هيثم بن طارق المعظم مسيرة «النهضة المتجددة»، التي تُوّجت بإطلاق «رؤية عُمان 2040»، وتحديث النظام الأساسي للدولة، وتطوير الجهاز الإداري، وتعزيز اللامركزية الإدارية في المحافظات، وبناء اقتصاد متنوع ومستدام.', 'تمثل الدوله البوسعيديه المرحله التاريخيه والسياسيه الممتده في سلطنه عمان منذ منتصف القرن الثامن عشر الميلادي وحتي العصر الحاضر تاسست الدوله عام 1744م عندما بويع الامام احمد بن سعيد البوسعيدي الذي كان واليا علي صحار اماما لعمان بعد نجاحه في توحيد البلاد وانهاء الانقسامات الداخليه وحمايه السياده الوطنيه علي السواحل العمانيه شهدت عمان في عهد الدوله البوسعيديه تحولا استراتيجيا كبيرا اذ عززت مكانتها البحريه والتجاريه في المحيط الهندي وبحر العرب وشرق افريقيا وازدهرت المواني العمانيه مثل مسقط وصحار وصور بوصفها مراكز للتبادل التجاري والدبلوماسي الدولي وفي عهد السيد سعيد بن سلطان البوسعيدي 1806 1856م بلغت العلاقات الدوليه والتجاريه ذروتها حيث اقامت عمان علاقات دبلوماسيه ومعاهدات تجاريه موثقه مع قوي عالميه كالولايات المتحده الامريكيه عام 1833م وبريطانيا وفرنسا وفي العصر الحديث انطلقت مسيره النهضه العمانيه الحديثه في 23 يوليو 1970م بقياده السلطان الراحل قابوس بن سعيد بن تيمور طيب الله ثراه الذي ارسي دعايم دوله الموسسات والقانون وبني البنيه الاساسيه الشامله في التعليم والصحه والاقتصاد والعلاقات الخارجيه المتوازنه القايمه علي السلام وحسن الجوار ومنذ 11 يناير 2020م يقود حضره صاحب الجلاله السلطان هيثم بن طارق المعظم مسيره النهضه المتجدده التي توجت باطلاق رويه عمان 2040 وتحديث النظام الاساسي للدوله وتطوير الجهاز الاداري وتعزيز اللامركزيه الاداريه في المحافظات وبناء اقتصاد متنوع ومستدام', 'cat-07-sultans-rulers', 'الدولة البوسعيدية', 'vol-02', '["الدولة البوسعيدية","أحمد بن سعيد البوسعيدي","قابوس بن سعيد","هيثم بن طارق","النهضة المتجددة","تاريخ عُمان","1744"]'::jsonb, 'الدوله البوسعيديه احمد بن سعيد البوسعيدي قابوس بن سعيد هيثم بن طارق النهضه المتجدده تاريخ عمان 1744', 'هيئة تحرير الموسوعة (استناداً إلى البوابة الإعلامية لسلطنة عُمان والمتحف الوطني)', 'src-omaninfo', 'https://www.omaninfo.om', '[{"title":"تاريخ سلطنة عُمان والدولة البوسعيدية — البوابة الإعلامية","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"قاعة التاريخ والدولة البوسعيدية — المتحف الوطني العُماني","url":"https://www.nm.gov.om","publisher":"المتحف الوطني بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"cultural_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المصادر الرسمية العُمانية', '[]'::jsonb, '9aa34edc9854784bebef16a50db7319b', 342, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-02-governorates-overview', 'administrative-governorates-of-oman', 'التقسيم الإداري لسلطنة عُمان: المحافظات الإحدى عشرة والولايات', 'التقسيم الاداري لسلطنه عمان المحافظات الاحدي عشره والولايات', 'تنقسم سلطنة عُمان إدارياً إلى 11 محافظة تضم 63 ولاية، ويُعد نظام المحافظات والمجالس البلدية ركيزة أساسية لتطبيق اللامركزية الإدارية وتنمية المحافظات ضمن رؤية عُمان 2040.', 'تنقسم سلطنه عمان اداريا الي 11 محافظه تضم 63 ولايه ويعد نظام المحافظات والمجالس البلديه ركيزه اساسيه لتطبيق اللامركزيه الاداريه وتنميه المحافظات ضمن رويه عمان 2040', 'يعتمد التنظيم الإداري في سلطنة عُمان على تقسيم أراضي السلطنة إلى إحدى عشرة (11) محافظة، يتبع كلاً منها عدد من الولايات يبلغ مجموعها 63 ولاية، وتُدار شؤون التنمية المحلية فيها وفق نظام المحافظات وقانون المجالس البلدية اللذين يعززان مبدأ اللامركزية الإدارية والاقتصادية.

وتشمل محافظات سلطنة عُمان:
1. محافظة مسقط: العاصمة السياسية والاقتصادية والإدارية ومقر الحكم، وتضم ست ولايات هي: مسقط، مطرح، بوشر، السيب، العامرات، وقريات.
2. محافظة ظفار: تقع في أقصى جنوب السلطنة، وهي أرض اللبان والتنوع البيئي وموسم الخريف، ومركزها ولاية صلالة، وتضم 10 ولايات منها طاقة، مرباط، رخيوت، ضلكوت، ثمريت، سدح، المزيونة، مقشن، وشليم وجزر الحلانيات.
3. محافظة مسندم: تقع في أقصى الشمال وتشرف على مضيق هرمز الاستراتيجي، وتضم أربع ولايات هي: خصب، بخاء، دبا، ومدحاء.
4. محافظة البريمي: تقع في الركن الشمالي الغربي للسلطنة، وتضم ثلاث ولايات هي: البريمي، محضة، والسنينة.
5. محافظة الداخلية: تمثل العمق التاريخي والثقافي للسلطنة، ومركزها ولاية نزوى، وتضم ولايات بهلا، منح، الحمراء، أدم، إزكي، سمائل، بدبد، والجبل الأخضر.
6. محافظة شمال الباطنة: تمتد على ساحل بحر عُمان وتُعد ثقلاً صناعياً وتجارياً ومينائياً، ومركزها ولاية صحار، وتضم ولايات شناص، لوى، صحم، الخابورة، والسويق.
7. محافظة جنوب الباطنة: تضم ولايات الرستاق، العوابي، نخل، وادي المعاول، بركاء، والمصنعة.
8. محافظة جنوب الشرقية: تطل على بحر عُمان وبحر العرب، ومركزها ولاية صور، وتضم ولايات الكامل والوافي، جعلان بني بو حسن، جعلان بني بو علي، ومصيرة.
9. محافظة شمال الشرقية: تضم ولايات إبراء، المضيبي، سناو، بدية، القابل، دماء والطائيين، ووادي بني خالد.
10. محافظة الظاهرة: تضم ولايات عبري، ينقل، وضنك.
11. محافظة الوسطى: تضم أربع ولايات هي: هيماء، محوت، الدقم، والجازر، وتحتضن المنطقة الاقتصادية الخاصة بالدقم ومشاريع الطاقة والمحميات الطبيعية.', 'يعتمد التنظيم الاداري في سلطنه عمان علي تقسيم اراضي السلطنه الي احدي عشره 11 محافظه يتبع كلا منها عدد من الولايات يبلغ مجموعها 63 ولايه وتدار شوون التنميه المحليه فيها وفق نظام المحافظات وقانون المجالس البلديه اللذين يعززان مبدا اللامركزيه الاداريه والاقتصاديه وتشمل محافظات سلطنه عمان 1 محافظه مسقط العاصمه السياسيه والاقتصاديه والاداريه ومقر الحكم وتضم ست ولايات هي مسقط مطرح بوشر السيب العامرات وقريات 2 محافظه ظفار تقع في اقصي جنوب السلطنه وهي ارض اللبان والتنوع البييي وموسم الخريف ومركزها ولايه صلاله وتضم 10 ولايات منها طاقه مرباط رخيوت ضلكوت ثمريت سدح المزيونه مقشن وشليم وجزر الحلانيات 3 محافظه مسندم تقع في اقصي الشمال وتشرف علي مضيق هرمز الاستراتيجي وتضم اربع ولايات هي خصب بخاء دبا ومدحاء 4 محافظه البريمي تقع في الركن الشمالي الغربي للسلطنه وتضم ثلاث ولايات هي البريمي محضه والسنينه 5 محافظه الداخليه تمثل العمق التاريخي والثقافي للسلطنه ومركزها ولايه نزوي وتضم ولايات بهلا منح الحمراء ادم ازكي سمايل بدبد والجبل الاخضر 6 محافظه شمال الباطنه تمتد علي ساحل بحر عمان وتعد ثقلا صناعيا وتجاريا وميناييا ومركزها ولايه صحار وتضم ولايات شناص لوي صحم الخابوره والسويق 7 محافظه جنوب الباطنه تضم ولايات الرستاق العوابي نخل وادي المعاول بركاء والمصنعه 8 محافظه جنوب الشرقيه تطل علي بحر عمان وبحر العرب ومركزها ولايه صور وتضم ولايات الكامل والوافي جعلان بني بو حسن جعلان بني بو علي ومصيره 9 محافظه شمال الشرقيه تضم ولايات ابراء المضيبي سناو بديه القابل دماء والطاييين ووادي بني خالد 10 محافظه الظاهره تضم ولايات عبري ينقل وضنك 11 محافظه الوسطي تضم اربع ولايات هي هيماء محوت الدقم والجازر وتحتضن المنطقه الاقتصاديه الخاصه بالدقم ومشاريع الطاقه والمحميات الطبيعيه', 'cat-02-governorates', 'المحافظات والولايات الإدارية', 'vol-01', '["محافظات سلطنة عُمان","مسقط","ظفار","مسندم","الداخلية","الباطنة","الشرقية","الوسطى","الظاهرة","البريمي","الولايات"]'::jsonb, 'محافظات سلطنه عمان مسقط ظفار مسندم الداخليه الباطنه الشرقيه الوسطي الظاهره البريمي الولايات', 'هيئة تحرير الموسوعة (استناداً إلى البوابة الإعلامية لسلطنة عُمان)', 'src-omaninfo', 'https://www.omaninfo.om', '[{"title":"محافظات سلطنة عُمان — البوابة الإعلامية لسلطنة عُمان","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"أولوية تنمية المحافظات والمدن المستدامة — رؤية عُمان 2040","url":"https://www.oman2040.om","publisher":"وحدة متابعة تنفيذ رؤية عُمان 2040","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المصادر الرسمية العُمانية', '[]'::jsonb, '41be19fdb595867b4bb2da5ecb550fdf', 291, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-03-bahla-fort-unesco', 'bahla-fort-and-historic-oasis', 'قلعة بهلا وواحتها التاريخية (أول موقع عُماني في قائمة التراث العالمي)', 'قلعه بهلا وواحتها التاريخيه اول موقع عماني في قايمه التراث العالمي', 'تُعد قلعة بهلا وواحتها في محافظة الداخلية أول معلم ثقافي عُماني يُدرج في قائمة التراث العالمي لمنظمة اليونسكو عام 1987م، وتشتهر بعمارتها الطينية الضخمة وسورها التاريخي.', 'تعد قلعه بهلا وواحتها في محافظه الداخليه اول معلم ثقافي عماني يدرج في قايمه التراث العالمي لمنظمه اليونسكو عام 1987م وتشتهر بعمارتها الطينيه الضخمه وسورها التاريخي', 'تقع قلعة بهلا في ولاية بهلا بمحافظة الداخلية، وتُعد من أقدم وأضخم القلاع التاريخية في سلطنة عُمان وشبه الجزيرة العربية. أُدرجت القلعة وواحتها المحيطة بها في قائمة التراث العالمي التابعة لمنظمة الأمم المتحدة للتربية والعلم والثقافة (اليونسكو) عام 1987م، لتكون بذلك أول موقع ثقافي عُماني ينال هذا التصنيف الدولي.

تتميز قلعة بهلا بعمارتها الدفاعية المشيدة من الطين واللبن (الآجر غير المشوي) والحجارة على تلة مرتفعة تشرف على الواحة والأسواق التقليدية وحارات بهلا القديمة. وتتكامل القلعة مع سور بهلا التاريخي الذي يمتد لمسافة تقارب اثني عشر كيلومتراً حول الواحة، مزوداً بأبراج مراقبة وبوابات دفاعية (صباحات) كانت تحمي المزارع والأفلاج والتجمعات السكنية.

تضم القلعة عدة أجزاء تاريخية تعود إلى حقب زمنية متعاقبة، من أبرزها «القصبة» القديمة التي يرجع تاريخ أجزائها الأولى إلى ما قبل الإسلام، و«بيت الجبل» و«بيت الحديث» اللذان شُيدا في عهد دولة النباهنة ودولة اليعاربة. وقد نفذت سلطنة عُمان بالتعاون مع خبراء منظمة اليونسكو مشروعاً علمياً شاملاً لترميم القلعة والحفاظ على تقنيات البناء الطيني التقليدي وأنظمة تصريف المياه فيها.', 'تقع قلعه بهلا في ولايه بهلا بمحافظه الداخليه وتعد من اقدم واضخم القلاع التاريخيه في سلطنه عمان وشبه الجزيره العربيه ادرجت القلعه وواحتها المحيطه بها في قايمه التراث العالمي التابعه لمنظمه الامم المتحده للتربيه والعلم والثقافه اليونسكو عام 1987م لتكون بذلك اول موقع ثقافي عماني ينال هذا التصنيف الدولي تتميز قلعه بهلا بعمارتها الدفاعيه المشيده من الطين واللبن الاجر غير المشوي والحجاره علي تله مرتفعه تشرف علي الواحه والاسواق التقليديه وحارات بهلا القديمه وتتكامل القلعه مع سور بهلا التاريخي الذي يمتد لمسافه تقارب اثني عشر كيلومترا حول الواحه مزودا بابراج مراقبه وبوابات دفاعيه صباحات كانت تحمي المزارع والافلاج والتجمعات السكنيه تضم القلعه عده اجزاء تاريخيه تعود الي حقب زمنيه متعاقبه من ابرزها القصبه القديمه التي يرجع تاريخ اجزايها الاولي الي ما قبل الاسلام و بيت الجبل و بيت الحديث اللذان شيدا في عهد دوله النباهنه ودوله اليعاربه وقد نفذت سلطنه عمان بالتعاون مع خبراء منظمه اليونسكو مشروعا علميا شاملا لترميم القلعه والحفاظ علي تقنيات البناء الطيني التقليدي وانظمه تصريف المياه فيها', 'cat-05-castles-forts', 'القلاع المدرجة في اليونسكو', 'vol-03', '["قلعة بهلا","التراث العالمي","اليونسكو","محافظة الداخلية","القلاع والحصون","العمارة الطينية","سور بهلا"]'::jsonb, 'قلعه بهلا التراث العالمي اليونسكو محافظه الداخليه القلاع والحصون العماره الطينيه سور بهلا', 'هيئة تحرير الموسوعة (استناداً إلى اليونسكو ووزارة التراث والسياحة)', 'src-unesco-om', 'https://whc.unesco.org/ar/statesparties/om', '[{"title":"قلعة بهلا (إدراج عام 1987م) — مركز التراث العالمي باليونسكو","url":"https://whc.unesco.org/ar/statesparties/om","publisher":"منظمة اليونسكو (UNESCO)","accessDate":"2026-10-16","sourceType":"international"},{"title":"القلاع والحصون التاريخية في سلطنة عُمان — البوابة الإعلامية","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من اليونسكو والمصادر العُمانية الرسمية', '[]'::jsonb, '3fd35b4448c94c8770e2996dc060e0f8', 254, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-04-omani-aflaj-system', 'omani-aflaj-irrigation-systems', 'أنظمة الري بالأفلاج العُمانية: هندسة المياه المستدامة والتراث العالمي', 'انظمه الري بالافلاج العمانيه هندسه المياه المستدامه والتراث العالمي', 'تمثل الأفلاج العُمانية نظاماً هندسياً واجتماعياً عريقاً لإدارة وتوزيع المياه بالاعتماد على الجاذبية الأرضية، وقد أدرجت اليونسكو خمسة أفلاج عُمانية في قائمة التراث العالمي عام 2006م.', 'تمثل الافلاج العمانيه نظاما هندسيا واجتماعيا عريقا لاداره وتوزيع المياه بالاعتماد علي الجاذبيه الارضيه وقد ادرجت اليونسكو خمسه افلاج عمانيه في قايمه التراث العالمي عام 2006م', 'تُعد الأفلاج العُمانية (جمع فَلَج) ابتكاراً هندسياً وحضارياً فريداً طوره الإنسان العُماني منذ قرون طويلة لاستخراج المياه الجوفية ومياه العيون والأودية ونقلها عبر قنوات محفورة بدقة عالية بالاعتماد الكلي على الجاذبية الأرضية دون استخدام مضخات آلية، لتروي الواحات الزراعية والتجمعات السكانية في بيئة شحيحة الأمطار.

تنقسم الأفلاج في سلطنة عُمان من حيث مصدر مياهها وبنيتها الهندسية إلى ثلاثة أنواع رئيسية:
1. الأفلاج الداؤودية (العدّية): وهي قنوات جوفية عميقة تمتد لكيلومترات من «أم الفلج» عند سفوح الجبال حتى تخرج إلى سطح الأرض في «الشريعة»، وتتميز بثبات جريانها طوال العام.
2. الأفلاج الغيلية: تعتمد على المياه السطحية وشبه السطحية الجارية في بطون الأودية، وتكون قنواتها قريبة من السطح.
3. الأفلاج العينية: تستمد مياهها مباشرة من العيون والينابيع الطبيعية الجبلية (مثل فلج الجيلة وفلج عين الكسفة).

وفي عام 2006م، أدرجت منظمة اليونسكو خمسة أفلاج عُمانية في قائمة التراث العالمي لتمثل أكثر من ثلاثة آلاف فلج حي لا يزال يعمل في سلطنة عُمان، وهذه الأفلاج الخمسة هي:
- فلج دارس (ولاية نزوى — محافظة الداخلية).
- فلج الخطمين (بركة الموز، ولاية نزوى — محافظة الداخلية).
- فلج الملكي (ولاية إزكي — محافظة الداخلية).
- فلج الميسر (ولاية الرستاق — محافظة جنوب الباطنة).
- فلج الجيلة (ولاية صور — محافظة جنوب الشرقية).

ويُدار كل فلج بنظام إداري واجتماعي دقيق يشرف عليه «العريف» و«الوكيل»، وتُقسّم حصص المياه زمنياً بنظام «الأثر» و«البادة»، وقد اعتمد المزارعون العُمانيون تاريخياً على «اللمد» (المزولة الشمسية نهاراً) وحركة النجوم ليلاً لضبط عدالة توزيع المياه.', 'تعد الافلاج العمانيه جمع فلج ابتكارا هندسيا وحضاريا فريدا طوره الانسان العماني منذ قرون طويله لاستخراج المياه الجوفيه ومياه العيون والاوديه ونقلها عبر قنوات محفوره بدقه عاليه بالاعتماد الكلي علي الجاذبيه الارضيه دون استخدام مضخات اليه لتروي الواحات الزراعيه والتجمعات السكانيه في بييه شحيحه الامطار تنقسم الافلاج في سلطنه عمان من حيث مصدر مياهها وبنيتها الهندسيه الي ثلاثه انواع رييسيه 1 الافلاج الداووديه العديه وهي قنوات جوفيه عميقه تمتد لكيلومترات من ام الفلج عند سفوح الجبال حتي تخرج الي سطح الارض في الشريعه وتتميز بثبات جريانها طوال العام 2 الافلاج الغيليه تعتمد علي المياه السطحيه وشبه السطحيه الجاريه في بطون الاوديه وتكون قنواتها قريبه من السطح 3 الافلاج العينيه تستمد مياهها مباشره من العيون والينابيع الطبيعيه الجبليه مثل فلج الجيله وفلج عين الكسفه وفي عام 2006م ادرجت منظمه اليونسكو خمسه افلاج عمانيه في قايمه التراث العالمي لتمثل اكثر من ثلاثه الاف فلج حي لا يزال يعمل في سلطنه عمان وهذه الافلاج الخمسه هي فلج دارس ولايه نزوي محافظه الداخليه فلج الخطمين بركه الموز ولايه نزوي محافظه الداخليه فلج الملكي ولايه ازكي محافظه الداخليه فلج الميسر ولايه الرستاق محافظه جنوب الباطنه فلج الجيله ولايه صور محافظه جنوب الشرقيه ويدار كل فلج بنظام اداري واجتماعي دقيق يشرف عليه العريف و الوكيل وتقسم حصص المياه زمنيا بنظام الاثر و الباده وقد اعتمد المزارعون العمانيون تاريخيا علي اللمد المزوله الشمسيه نهارا وحركه النجوم ليلا لضبط عداله توزيع المياه', 'cat-08-heritage-traditions', 'أنظمة الري بالأفلاج', 'vol-03', '["الأفلاج العُمانية","فلج دارس","فلج الخطمين","فلج الملكي","فلج الميسر","فلج الجيلة","اليونسكو","هندسة المياه"]'::jsonb, 'الافلاج العمانيه فلج دارس فلج الخطمين فلج الملكي فلج الميسر فلج الجيله اليونسكو هندسه المياه', 'هيئة تحرير الموسوعة (استناداً إلى المتحف الوطني العُماني واليونسكو)', 'src-national-museum', 'https://www.nm.gov.om', '[{"title":"أنظمة الري بالأفلاج في عُمان (إدراج 2006م) — مركز التراث العالمي","url":"https://whc.unesco.org/ar/statesparties/om","publisher":"منظمة اليونسكو (UNESCO)","accessDate":"2026-10-16","sourceType":"international"},{"title":"الأفلاج العُمانية — المتحف الوطني بسلطنة عُمان","url":"https://www.nm.gov.om","publisher":"المتحف الوطني بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"cultural_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المتحف الوطني واليونسكو', '[]'::jsonb, 'b7c9f0c43542f2da1259a659f84eb692', 310, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-05-ahmad-ibn-majid', 'ahmad-ibn-majid-al-saadi', 'الملاح العُماني شهاب الدين أحمد بن ماجد السعدي (أسد البحار)', 'الملاح العماني شهاب الدين احمد بن ماجد السعدي اسد البحار', 'رائد علم الملاحة البحرية الفلكية في المحيط الهندي في القرن التاسع الهجري / الخامس عشر الميلادي، وصاحب كتاب «الفوائد في أصول علم البحر والقواعد» والأراجيز الملاحية الشهيرة.', 'رايد علم الملاحه البحريه الفلكيه في المحيط الهندي في القرن التاسع الهجري الخامس عشر الميلادي وصاحب كتاب الفوايد في اصول علم البحر والقواعد والاراجيز الملاحيه الشهيره', 'يُعد شهاب الدين أحمد بن ماجد بن محمد السعدي العُماني (المعروف بلقب «أسد البحار» و«معلم بحر الهند») أحد أعظم الملاحين والعلماء الجغرافيين في التاريخ البحري الإسلامي والعالمي خلال القرن التاسع الهجري / الخامس عشر الميلادي.

نشأ أحمد بن ماجد في بيئة بحرية عُمانية عريقة متوارثة للملاحة؛ إذ كان أبوه وجده من ربابنة البحر المشهورين («المعالمة») الذين خبروا مسالك بحر عُمان وبحر العرب والبحر الأحمر والمحيط الهندي. جمع ابن ماجد بين الخبرة الميدانية الطويلة في قيادة السفن وبين التأصيل العلمي والرياضي والفلكي للملاحة البحرية، وأتقن العربية وعدة لغات كانت متداولة في موانئ المحيط الهندي.

ترك أحمد بن ماجد تراثاً علمياً ضخماً يزيد على أربعين مؤلفاً بين كتاب منثور وأرجوزة شعرية تعليمية، من أشهرها:
1. كتاب «الفوائد في أصول علم البحر والقواعد» (أتمه نحو عام 895هـ / 1490م): ويُعد موسوعة ملاحية شاملة شرح فيها منازل القمر، وقياسات النجوم بالاعتماد على آلة «الكمال» (الخشبات)، والرياح الموسمية (المواسم)، والتيارات البحرية، والمسافات بين الموانئ («الزروع»)، وعلامات القرب من السواحل والجزر.
2. أرجوزة «حاوية الاختصار في أصول علم البحار»: وهي منظومة شعرية مطولة تضم أكثر من ألف بيت تجمع قواعد الملاحة الفلكية.
3. «الأرجوزة السفالية» وغيرها من الأراجيز التي وثقت خطوط الملاحة نحو ساحل شرق أفريقيا (سفالة وزنجبار) والهند وجنوب شرق آسيا.

ويحتفي المتحف الوطني بسلطنة عُمان في «قاعة التاريخ البحري» بإسهامات أحمد بن ماجد ومخطوطاته النادرة وأدوات الرصد الفلكي البحري التي استخدمها الملاحون العُمانيون.', 'يعد شهاب الدين احمد بن ماجد بن محمد السعدي العماني المعروف بلقب اسد البحار و معلم بحر الهند احد اعظم الملاحين والعلماء الجغرافيين في التاريخ البحري الاسلامي والعالمي خلال القرن التاسع الهجري الخامس عشر الميلادي نشا احمد بن ماجد في بييه بحريه عمانيه عريقه متوارثه للملاحه اذ كان ابوه وجده من ربابنه البحر المشهورين المعالمه الذين خبروا مسالك بحر عمان وبحر العرب والبحر الاحمر والمحيط الهندي جمع ابن ماجد بين الخبره الميدانيه الطويله في قياده السفن وبين التاصيل العلمي والرياضي والفلكي للملاحه البحريه واتقن العربيه وعده لغات كانت متداوله في مواني المحيط الهندي ترك احمد بن ماجد تراثا علميا ضخما يزيد علي اربعين مولفا بين كتاب منثور وارجوزه شعريه تعليميه من اشهرها 1 كتاب الفوايد في اصول علم البحر والقواعد اتمه نحو عام 895ه 1490م ويعد موسوعه ملاحيه شامله شرح فيها منازل القمر وقياسات النجوم بالاعتماد علي اله الكمال الخشبات والرياح الموسميه المواسم والتيارات البحريه والمسافات بين المواني الزروع وعلامات القرب من السواحل والجزر 2 ارجوزه حاويه الاختصار في اصول علم البحار وهي منظومه شعريه مطوله تضم اكثر من الف بيت تجمع قواعد الملاحه الفلكيه 3 الارجوزه السفاليه وغيرها من الاراجيز التي وثقت خطوط الملاحه نحو ساحل شرق افريقيا سفاله وزنجبار والهند وجنوب شرق اسيا ويحتفي المتحف الوطني بسلطنه عمان في قاعه التاريخ البحري باسهامات احمد بن ماجد ومخطوطاته النادره وادوات الرصد الفلكي البحري التي استخدمها الملاحون العمانيون', 'cat-06-personalities', 'رواد الملاحة والفلك', 'vol-04', '["أحمد بن ماجد","أسد البحار","الملاحة البحرية","الفوائد في أصول علم البحر والقواعد","المتحف الوطني","التاريخ البحري العُماني"]'::jsonb, 'احمد بن ماجد اسد البحار الملاحه البحريه الفوايد في اصول علم البحر والقواعد المتحف الوطني التاريخ البحري العماني', 'هيئة تحرير الموسوعة (استناداً إلى المتحف الوطني العُماني والبوابة الإعلامية)', 'src-national-museum', 'https://www.nm.gov.om', '[{"title":"قاعة التاريخ البحري وإصدارات أحمد بن ماجد — المتحف الوطني العُماني","url":"https://www.nm.gov.om","publisher":"المتحف الوطني بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"cultural_omani"},{"title":"أعلام وشخصيات عُمانية خالدة — البوابة الإعلامية لسلطنة عُمان","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المتحف الوطني العُماني', '[]'::jsonb, '7e30124435fb15339bc45c88740c7026', 279, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-06-al-khalil-al-farahidi', 'al-khalil-ibn-ahmad-al-farahidi', 'الإمام الخليل بن أحمد الفراهيدي الأزدي العُماني (واضع علم العروض ومعجم العين)', 'الامام الخليل بن احمد الفراهيدي الازدي العماني واضع علم العروض ومعجم العين', 'العالم اللغوي العُماني الفذ في القرن الثاني الهجري (100–170هـ تقريباً)، واضع علم العروض وأوزان الشعر العربي، ومؤلف «كتاب العين» أول معجم شامل في تاريخ اللغة العربية.', 'العالم اللغوي العماني الفذ في القرن الثاني الهجري 100 170ه تقريبا واضع علم العروض واوزان الشعر العربي ومولف كتاب العين اول معجم شامل في تاريخ اللغه العربيه', 'هو أبو عبد الرحمن الخليل بن أحمد بن عمرو بن تميم الفراهيدي الأزدي اليحمدي العُماني، وُلد في عُمان في مطلع القرن الثاني الهجري (نحو عام 100هـ / 718م)، ثم انتقل إلى البصرة حيث برز بوصفه إمام علوم العربية وأحد أعظم العقول العلمية والرياضية في الحضارة الإسلامية.

تتمثل أبرز إنجازات الخليل بن أحمد الفراهيدي العلمية واللغوية في:
1. تأسيس «علم العروض»: استنبط الخليل بن أحمد بحور الشعر العربي الخمسة عشر (ثم زاد تلميذه الأخفش بحر المتدارك فصارت ستة عشر بحراً)، وضبط تفعيلاتها ودوائرها العروضية على أسس صوتية وإيقاعية دقيقة لم يُسبق إليها.
2. تأليف «كتاب العين» (أول معجم في اللغة العربية): ابتكر الفراهيدي منهجاً رياضياً وصوتياً لحصر مفردات اللغة العربية ومنع ضياعها، فرتّب الحروف بحسب مخارجها الصوتية بدءاً من أعمق حروف الحلق وهو حرف «العين»، واعتمد نظام التقاليب الرياضية لحصر جميع التراكيب الثنائية والثلاثية والرباعية والخماسية الممكنة في اللسان العربي والتمييز بين «المستعمل» و«المهمل» منها.
3. تطوير ضبط المصحف الشريف والكتابة العربية: ابتكر علامات الضبط والتشكيل المعروفة اليوم (الفتحة والضمة والكسرة والشدة والسكون والهمزة) بدلاً من نظام النقط الملونة القديم، مما يسر قراءة النص العربي وحفظه من اللحن.
4. التأسيس لمدرسة النحو العربي: كان الخليل الأستاذ الأول لإمام النحاة سيبويه، وأغلب الشواهد والقواعد التحليلية في «الكتاب» لسيبويه مروية عن الخليل بن أحمد الفراهيدي.', 'هو ابو عبد الرحمن الخليل بن احمد بن عمرو بن تميم الفراهيدي الازدي اليحمدي العماني ولد في عمان في مطلع القرن الثاني الهجري نحو عام 100ه 718م ثم انتقل الي البصره حيث برز بوصفه امام علوم العربيه واحد اعظم العقول العلميه والرياضيه في الحضاره الاسلاميه تتمثل ابرز انجازات الخليل بن احمد الفراهيدي العلميه واللغويه في 1 تاسيس علم العروض استنبط الخليل بن احمد بحور الشعر العربي الخمسه عشر ثم زاد تلميذه الاخفش بحر المتدارك فصارت سته عشر بحرا وضبط تفعيلاتها ودوايرها العروضيه علي اسس صوتيه وايقاعيه دقيقه لم يسبق اليها 2 تاليف كتاب العين اول معجم في اللغه العربيه ابتكر الفراهيدي منهجا رياضيا وصوتيا لحصر مفردات اللغه العربيه ومنع ضياعها فرتب الحروف بحسب مخارجها الصوتيه بدءا من اعمق حروف الحلق وهو حرف العين واعتمد نظام التقاليب الرياضيه لحصر جميع التراكيب الثناييه والثلاثيه والرباعيه والخماسيه الممكنه في اللسان العربي والتمييز بين المستعمل و المهمل منها 3 تطوير ضبط المصحف الشريف والكتابه العربيه ابتكر علامات الضبط والتشكيل المعروفه اليوم الفتحه والضمه والكسره والشده والسكون والهمزه بدلا من نظام النقط الملونه القديم مما يسر قراءه النص العربي وحفظه من اللحن 4 التاسيس لمدرسه النحو العربي كان الخليل الاستاذ الاول لامام النحاه سيبويه واغلب الشواهد والقواعد التحليليه في الكتاب لسيبويه مرويه عن الخليل بن احمد الفراهيدي', 'cat-10-literature-poetry', 'المعاجم وعلم العروض', 'vol-04', '["الخليل بن أحمد الفراهيدي","كتاب العين","علم العروض","اللغة العربية","الأعلام العُمانيون","النحو العربي"]'::jsonb, 'الخليل بن احمد الفراهيدي كتاب العين علم العروض اللغه العربيه الاعلام العمانيون النحو العربي', 'هيئة تحرير الموسوعة (استناداً إلى وكالة الأنباء العُمانية والمتحف الوطني)', 'src-omannews', 'https://omannews.gov.om', '[{"title":"الخليل بن أحمد الفراهيدي وإسهاماته اللغوية — وكالة الأنباء العُمانية","url":"https://omannews.gov.om","publisher":"وكالة الأنباء العُمانية (ONA)","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"الأعلام والعلماء العُمانيون — المتحف الوطني بسلطنة عُمان","url":"https://www.nm.gov.om","publisher":"المتحف الوطني بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"cultural_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المصادر الرسمية العُمانية', '[]'::jsonb, '5d979b4f34bd4ca4f9ddfbfaf9361e18', 230, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-07-al-jabal-al-akhdar', 'al-jabal-al-akhdar-hajar-mountains', 'الجبل الأخضر وسلسلة جبال الحجر: التضاريس والمدرجات الزراعية', 'الجبل الاخضر وسلسله جبال الحجر التضاريس والمدرجات الزراعيه', 'يقع الجبل الأخضر ضمن سلسلة جبال الحجر الغربي في محافظة الداخلية على ارتفاع يقارب 3,000 متر فوق سطح البحر، ويشتهر بمدرجاته الزراعية الفريدة وإنتاج الورد الجبلي والرمان.', 'يقع الجبل الاخضر ضمن سلسله جبال الحجر الغربي في محافظه الداخليه علي ارتفاع يقارب 3 000 متر فوق سطح البحر ويشتهر بمدرجاته الزراعيه الفريده وانتاج الورد الجبلي والرمان', 'تُشكّل سلسلة جبال الحجر العمود الفقري التضاريسي لشمال سلطنة عُمان، حيث تمتد في قوس جبلي مهيب من رؤوس الجبال في محافظة مسندم شمالاً حتى رأس الحد في محافظة جنوب الشرقية جنوباً، وتنقسم عبر «وادي سمائل» إلى جبال الحجر الغربي وجبال الحجر الشرقي.

وفي قلب جبال الحجر الغربي بمحافظة الداخلية تبرز ولاية «الجبل الأخضر»، التي يصل ارتفاع قممها إلى نحو 3,000 متر فوق سطح البحر (قريباً من قمة جبل شمس الذي يُعد أعلى قمة جبلية في سلطنة عُمان). ويمنح هذا الارتفاع الشاهق الجبل الأخضر مناخاً معتدلاً في فصل الصيف وبارداً في فصل الشتاء، مما أوجد بيئة زراعية ونباتية متفردة في شبه الجزيرة العربية.

ابتكر أهالي الجبل الأخضر عبر القرون نظام «المدرجات الزراعية» الحجرية المنحوتة في سفوح الجبال الصخرية في قرى مثل العين والشريجة وسيق ووادي بني حبيب، ورووها عبر الأفلاج الجبلية والعيون الطبيعية. وتشتهر هذه المدرجات بإنتاج محاصيل عالية الجودة، وفي مقدمتها:
- رمان الجبل الأخضر ذو الشهرة الواسعة.
- الورد الجبلي العُماني الذي يُقطّر منه «ماء الورد العُماني» في موسم الربيع (مارس وأبريل) داخل مصانع تقليدية تُعرف بـ «الدهجان».
- أشجار الجوز واللوز والمشمش والخوخ والزعفران والتين.

كما يضم الجبل الأخضر محمية المناظر الطبيعية التي تحمي أشجار العلعلان (العرعر الجبلي) والزيتون البري (العتم) والحياة الفطرية الجبلية.', 'تشكل سلسله جبال الحجر العمود الفقري التضاريسي لشمال سلطنه عمان حيث تمتد في قوس جبلي مهيب من رووس الجبال في محافظه مسندم شمالا حتي راس الحد في محافظه جنوب الشرقيه جنوبا وتنقسم عبر وادي سمايل الي جبال الحجر الغربي وجبال الحجر الشرقي وفي قلب جبال الحجر الغربي بمحافظه الداخليه تبرز ولايه الجبل الاخضر التي يصل ارتفاع قممها الي نحو 3 000 متر فوق سطح البحر قريبا من قمه جبل شمس الذي يعد اعلي قمه جبليه في سلطنه عمان ويمنح هذا الارتفاع الشاهق الجبل الاخضر مناخا معتدلا في فصل الصيف وباردا في فصل الشتاء مما اوجد بييه زراعيه ونباتيه متفرده في شبه الجزيره العربيه ابتكر اهالي الجبل الاخضر عبر القرون نظام المدرجات الزراعيه الحجريه المنحوته في سفوح الجبال الصخريه في قري مثل العين والشريجه وسيق ووادي بني حبيب ورووها عبر الافلاج الجبليه والعيون الطبيعيه وتشتهر هذه المدرجات بانتاج محاصيل عاليه الجوده وفي مقدمتها رمان الجبل الاخضر ذو الشهره الواسعه الورد الجبلي العماني الذي يقطر منه ماء الورد العماني في موسم الربيع مارس وابريل داخل مصانع تقليديه تعرف ب الدهجان اشجار الجوز واللوز والمشمش والخوخ والزعفران والتين كما يضم الجبل الاخضر محميه المناظر الطبيعيه التي تحمي اشجار العلعلان العرعر الجبلي والزيتون البري العتم والحياه الفطريه الجبليه', 'cat-03-geography', 'سلسلة جبال الحجر والجبل الأخضر', 'vol-01', '["الجبل الأخضر","سلسلة جبال الحجر","محافظة الداخلية","المدرجات الزراعية","ماء الورد","رمان الجبل الأخضر","جبل شمس"]'::jsonb, 'الجبل الاخضر سلسله جبال الحجر محافظه الداخليه المدرجات الزراعيه ماء الورد رمان الجبل الاخضر جبل شمس', 'هيئة تحرير الموسوعة (استناداً إلى البوابة الإعلامية ووزارة التراث والسياحة)', 'src-omaninfo', 'https://www.omaninfo.om', '[{"title":"جغرافيا سلطنة عُمان والجبل الأخضر — البوابة الإعلامية","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"المقومات السياحية والبيئية في الجبل الأخضر — وزارة التراث والسياحة","url":"https://mht.gov.om","publisher":"وزارة التراث والسياحة بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المصادر الرسمية العُمانية', '[]'::jsonb, '5746a34fba499efb10a0fbaf0c6f614f', 205, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-08-masirah-and-daymaniyat-islands', 'masirah-island-and-daymaniyat-archipelago', 'الجزر العُمانية: جزيرة مصيرة ومحمية جزر الديمانيات الطبيعية', 'الجزر العمانيه جزيره مصيره ومحميه جزر الديمانيات الطبيعيه', 'تزخر السواحل العُمانية بجزر ذات أهمية استراتيجية وبيئية عالمية، تتقدمها جزيرة مصيرة (أكبر جزر السلطنة) وأرخبيل جزر الديمانيات المحمية الطبيعية الغنية بالشعاب المرجانية والسلاحف.', 'تزخر السواحل العمانيه بجزر ذات اهميه استراتيجيه وبيييه عالميه تتقدمها جزيره مصيره اكبر جزر السلطنه وارخبيل جزر الديمانيات المحميه الطبيعيه الغنيه بالشعاب المرجانيه والسلاحف', 'يمتد الشريط الساحلي لسلطنة عُمان لأكثر من 3,165 كيلومتراً مطلاً على ثلاثة مسطحات مائية مهمة هي: الخليج العربي ومضيق هرمز، وبحر عُمان، وبحر العرب المتصل بالمحيط الهندي. وتنتشر على امتداد هذه السواحل عشرات الجزر والأرخبيلات البحرية ذات الأهمية البيئية والجغرافية العالية، ومن أبرزها:

أولاً: جزيرة مصيرة (محافظة جنوب الشرقية)
تُعد ولاية وجزيرة مصيرة أكبر جزيرة في سلطنة عُمان، وتقع في بحر العرب قبالة الساحل الجنوبي الشرقي للسلطنة، ويفصلها عن البر الرئيسي «خليج مصيرة». تتميز الجزيرة بتنوعها الأحيائي الفريد؛ إذ تُعد من أكبر مواطن تعشيش السلاحف البحرية في العالم، لا سيما «سلحفاة الريماني» (السلحفاة ضخمة الرأس)، إلى جانب السلحفاة الخضراء والسلحفاة الزيتونية وسلحفاة الشرفاف. كما تمثل الجزيرة محطة رئيسية للطيور المهاجرة ووجهة عالمية لرياضات الرياح البحرية وصيد الأسماك.

ثانياً: محمية جزر الديمانيات الطبيعية
يتكون أرخبيل جزر الديمانيات من تسع (9) جزر طبيعية غير مأهولة تقع في بحر عُمان قبالة سواحل ولاية السيب (محافظة مسقط) وولاية بركاء (محافظة جنوب الباطنة). أُعلنت جزر الديمانيات محمية طبيعية نظراً لما تحتضنه من شعاب مرجانية بكْر نادرة، وأسماك مرجانية ملونة، ومواقع لتعشيش سلاحف الشرفاف والسلاحف الخضراء، فضلاً عن آلاف الطيور البحرية مثل الصقر السخامي وخطاف البحر.

ثالثاً: جزر عُمانية أخرى بارزة
تشمل الجزر العُمانية الأخرى «جزر الحلانيات» الخمس في محافظة ظفار، و«جزيرة التلغراف» (مقلب) في خور شم بمحافظة مسندم، و«جزيرة المحوت» في محافظة الوسطى.', 'يمتد الشريط الساحلي لسلطنه عمان لاكثر من 3 165 كيلومترا مطلا علي ثلاثه مسطحات ماييه مهمه هي الخليج العربي ومضيق هرمز وبحر عمان وبحر العرب المتصل بالمحيط الهندي وتنتشر علي امتداد هذه السواحل عشرات الجزر والارخبيلات البحريه ذات الاهميه البيييه والجغرافيه العاليه ومن ابرزها اولا جزيره مصيره محافظه جنوب الشرقيه تعد ولايه وجزيره مصيره اكبر جزيره في سلطنه عمان وتقع في بحر العرب قباله الساحل الجنوبي الشرقي للسلطنه ويفصلها عن البر الرييسي خليج مصيره تتميز الجزيره بتنوعها الاحيايي الفريد اذ تعد من اكبر مواطن تعشيش السلاحف البحريه في العالم لا سيما سلحفاه الريماني السلحفاه ضخمه الراس الي جانب السلحفاه الخضراء والسلحفاه الزيتونيه وسلحفاه الشرفاف كما تمثل الجزيره محطه رييسيه للطيور المهاجره ووجهه عالميه لرياضات الرياح البحريه وصيد الاسماك ثانيا محميه جزر الديمانيات الطبيعيه يتكون ارخبيل جزر الديمانيات من تسع 9 جزر طبيعيه غير ماهوله تقع في بحر عمان قباله سواحل ولايه السيب محافظه مسقط وولايه بركاء محافظه جنوب الباطنه اعلنت جزر الديمانيات محميه طبيعيه نظرا لما تحتضنه من شعاب مرجانيه بكر نادره واسماك مرجانيه ملونه ومواقع لتعشيش سلاحف الشرفاف والسلاحف الخضراء فضلا عن الاف الطيور البحريه مثل الصقر السخامي وخطاف البحر ثالثا جزر عمانيه اخري بارزه تشمل الجزر العمانيه الاخري جزر الحلانيات الخمس في محافظه ظفار و جزيره التلغراف مقلب في خور شم بمحافظه مسندم و جزيره المحوت في محافظه الوسطي', 'cat-04-seas-islands', 'جزيرة مصيرة', 'vol-01', '["جزيرة مصيرة","جزر الديمانيات","جزر الحلانيات","السواحل العُمانية","بحر العرب","بحر عُمان","السلاحف البحرية"]'::jsonb, 'جزيره مصيره جزر الديمانيات جزر الحلانيات السواحل العمانيه بحر العرب بحر عمان السلاحف البحريه', 'هيئة تحرير الموسوعة (استناداً إلى هيئة البيئة والبوابة الإعلامية)', 'src-ea', 'https://www.ea.gov.om', '[{"title":"المحميات الطبيعية البحرية وجزر الديمانيات — هيئة البيئة","url":"https://www.ea.gov.om","publisher":"هيئة البيئة بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"جزيرة مصيرة والجزر العُمانية — البوابة الإعلامية لسلطنة عُمان","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من هيئة البيئة والبوابة الإعلامية', '[]'::jsonb, 'b95440506cf4c95bc48c89dc45c91def', 192, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-09-omani-arts-and-khanjar', 'omani-traditional-arts-and-khanjar-craft', 'الفنون العُمانية التقليدية (الرزحة والعازي) وصناعة الخنجر العُماني', 'الفنون العمانيه التقليديه الرزحه والعازي وصناعه الخنجر العماني', 'يجسد الخنجر العُماني وفنا الرزحة والعازي ركائز أصيلة من التراث الثقافي غير المادي والحرف اليدوية في سلطنة عُمان، وقد سُجل العديد منها في قوائم منظمة اليونسكو للتراث الإنساني.', 'يجسد الخنجر العماني وفنا الرزحه والعازي ركايز اصيله من التراث الثقافي غير المادي والحرف اليدويه في سلطنه عمان وقد سجل العديد منها في قوايم منظمه اليونسكو للتراث الانساني', 'يمتاز الموروث الثقافي في سلطنة عُمان بثراء الفنون الأدائية التقليدية والصناعات الحرفية المتقنة التي تعبر عن الهوية الوطنية والاعتزاز بالقيم العُمانية الأصيلة.

أولاً: فن الرزحة وفن العازي
1. الرزحة: تُعد من أعرق الفنون التقليدية الجماعية في سلطنة عُمان، وتُؤدى في المناسبات الوطنية والأعياد والأفراح. يصطف المشاركون في صفين متقابلين يتبادلان الشلات الشعرية (في أغراض الفخر والحماسة والحكمة والمطارحات الشعرية) على إيقاع طبلي «الكاسر» و«الرحماني»، بينما يتقدم المبارزون في الوسط لاستعراض المهارة والرشاقة في حمل السيف والترس.
2. العازي: فن إلقاء شعري تقليدي رفيع يُؤدى دون آلات موسيقية؛ حيث يتقدم شاعر ومؤدي العازي ممسكاً بسيفه أو عصاه، فيلقي قصيدة فخر واعتزاز بالوطن والقيم السامية بصوت جهوري، ويردد خلفه المشاركون لازمة صوتية موحدة (مثل: «أسميه وسلّم» أو «الرب سلّم»). وقد أُدرج فن العازي في القائمة التمثيلية للتراث الثقافي غير المادي لمنظمة اليونسكو عام 2012م.

ثانياً: صناعة الخنجر العُماني والحلوى العُمانية
- الخنجر العُماني: يُعد شعاراً وطنياً ورمزاً للأصالة والوجاهة في الزي العُماني الرسمي. يتكون الخنجر من «القرن» (المقبض) المزخرف بمسامير الفضة الدقيقة، و«الطوق»، و«النصل» الفولاذي المنحني، و«القطاعة» (الغمد) المزدانة بنقوش الفضة الخالصة أو الذهب وحلقات الحزام الجلدي المزركش بالأسلاك الفضية. وأُدرج الخنجر العُماني والمهارات المرتبطة به في قائمة التراث الثقافي غير المادي لليونسكو عام 2022م.
- الحلوى العُمانية: رمز الضيافة العُمانية الأصيلة إلى جانب القهوة العُمانية، وتُصنع في مراجل نحاسية على حطب السمر من النشا والسكر البني أو الأبيض والسمن العُماني وماء الورد الجبلي والزعفران والهيل والمكسرات.', 'يمتاز الموروث الثقافي في سلطنه عمان بثراء الفنون الاداييه التقليديه والصناعات الحرفيه المتقنه التي تعبر عن الهويه الوطنيه والاعتزاز بالقيم العمانيه الاصيله اولا فن الرزحه وفن العازي 1 الرزحه تعد من اعرق الفنون التقليديه الجماعيه في سلطنه عمان وتودي في المناسبات الوطنيه والاعياد والافراح يصطف المشاركون في صفين متقابلين يتبادلان الشلات الشعريه في اغراض الفخر والحماسه والحكمه والمطارحات الشعريه علي ايقاع طبلي الكاسر و الرحماني بينما يتقدم المبارزون في الوسط لاستعراض المهاره والرشاقه في حمل السيف والترس 2 العازي فن القاء شعري تقليدي رفيع يودي دون الات موسيقيه حيث يتقدم شاعر ومودي العازي ممسكا بسيفه او عصاه فيلقي قصيده فخر واعتزاز بالوطن والقيم الساميه بصوت جهوري ويردد خلفه المشاركون لازمه صوتيه موحده مثل اسميه وسلم او الرب سلم وقد ادرج فن العازي في القايمه التمثيليه للتراث الثقافي غير المادي لمنظمه اليونسكو عام 2012م ثانيا صناعه الخنجر العماني والحلوي العمانيه الخنجر العماني يعد شعارا وطنيا ورمزا للاصاله والوجاهه في الزي العماني الرسمي يتكون الخنجر من القرن المقبض المزخرف بمسامير الفضه الدقيقه و الطوق و النصل الفولاذي المنحني و القطاعه الغمد المزدانه بنقوش الفضه الخالصه او الذهب وحلقات الحزام الجلدي المزركش بالاسلاك الفضيه وادرج الخنجر العماني والمهارات المرتبطه به في قايمه التراث الثقافي غير المادي لليونسكو عام 2022م الحلوي العمانيه رمز الضيافه العمانيه الاصيله الي جانب القهوه العمانيه وتصنع في مراجل نحاسيه علي حطب السمر من النشا والسكر البني او الابيض والسمن العماني وماء الورد الجبلي والزعفران والهيل والمكسرات', 'cat-09-arts-crafts', 'الفنون الحماسية (الرزحة والعازي)', 'vol-05', '["الخنجر العُماني","فن الرزحة","فن العازي","الحلوى العُمانية","الفنون الشعبية","الحرف التقليدية","اليونسكو"]'::jsonb, 'الخنجر العماني فن الرزحه فن العازي الحلوي العمانيه الفنون الشعبيه الحرف التقليديه اليونسكو', 'هيئة تحرير الموسوعة (استناداً إلى وزارة الثقافة والرياضة والشباب والبوابة الإعلامية)', 'src-mcsy', 'https://mcsy.gov.om', '[{"title":"الفنون الشعبية والصناعات الحرفية العُمانية — البوابة الإعلامية","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"عناصر التراث الثقافي غير المادي المسجلة في اليونسكو — وزارة الثقافة والرياضة والشباب","url":"https://mcsy.gov.om","publisher":"وزارة الثقافة والرياضة والشباب","accessDate":"2026-10-16","sourceType":"cultural_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المصادر الثقافية العُمانية الرسمية', '[]'::jsonb, 'ca6853020861f4e2ac7701894bb7378c', 265, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-10-sultan-qaboos-university', 'sultan-qaboos-university-and-higher-education', 'جامعة السلطان قابوس ومسيرة التعليم العالي والبحث العلمي في عُمان', 'جامعه السلطان قابوس ومسيره التعليم العالي والبحث العلمي في عمان', 'افتتحت جامعة السلطان قابوس عام 1986م في ولاية السيب بمحافظة مسقط بوصفها الجامعة الحكومية الأولى في سلطنة عُمان، وتضم 9 كليات علمية وإنسانية ومراكز بحثية متخصصة.', 'افتتحت جامعه السلطان قابوس عام 1986م في ولايه السيب بمحافظه مسقط بوصفها الجامعه الحكوميه الاولي في سلطنه عمان وتضم 9 كليات علميه وانسانيه ومراكز بحثيه متخصصه', 'تُمثل جامعة السلطان قابوس الصرح الأكاديمي والعلمي الحكومي الأول في سلطنة عُمان. بدأ استقبال الدفعة الأولى من طلبتها في شهر سبتمبر عام 1986م في الحرم الجامعي بمنطقة الخوض بولاية السيب في محافظة مسقط، لتشكل نقلة نوعية في مسيرة التعليم العالي والبحث العلمي وبناء الكفاءات الوطنية العُمانية.

تضم جامعة السلطان قابوس تسع (9) كليات أكاديمية هي:
1. كلية الطب والعلوم الصحية (يرتبط بها مستشفى جامعة السلطان قابوس الجامعي).
2. كلية الهندسة.
3. كلية العلوم الزراعية والبحرية.
4. كلية التربية.
5. كلية العلوم.
6. كلية الآداب والعلوم الاجتماعية.
7. كلية الاقتصاد والعلوم السياسية.
8. كلية القانون.
9. كلية التمريض.

كما تحتضن الجامعة عدداً من المراكز البحثية المتخصصة ذات الأهمية الوطنية والإقليمية، ومن أبرزها: مركز الدراسات العُمانية، مركز أبحاث العلوم البحرية والتكنولوجيا الحيوية، مركز أبحاث المياه، مركز أبحاث النفط والغاز، ومركز أبحاث الطاقة المستدامة، فضلاً عن مبادراتها المشتركة في المنطقة الاقتصادية الخاصة بالدقم لربط مخرجات البحث العلمي بقطاعات الصناعة والاقتصاد الأزرق والطاقة المتجددة.', 'تمثل جامعه السلطان قابوس الصرح الاكاديمي والعلمي الحكومي الاول في سلطنه عمان بدا استقبال الدفعه الاولي من طلبتها في شهر سبتمبر عام 1986م في الحرم الجامعي بمنطقه الخوض بولايه السيب في محافظه مسقط لتشكل نقله نوعيه في مسيره التعليم العالي والبحث العلمي وبناء الكفاءات الوطنيه العمانيه تضم جامعه السلطان قابوس تسع 9 كليات اكاديميه هي 1 كليه الطب والعلوم الصحيه يرتبط بها مستشفي جامعه السلطان قابوس الجامعي 2 كليه الهندسه 3 كليه العلوم الزراعيه والبحريه 4 كليه التربيه 5 كليه العلوم 6 كليه الاداب والعلوم الاجتماعيه 7 كليه الاقتصاد والعلوم السياسيه 8 كليه القانون 9 كليه التمريض كما تحتضن الجامعه عددا من المراكز البحثيه المتخصصه ذات الاهميه الوطنيه والاقليميه ومن ابرزها مركز الدراسات العمانيه مركز ابحاث العلوم البحريه والتكنولوجيا الحيويه مركز ابحاث المياه مركز ابحاث النفط والغاز ومركز ابحاث الطاقه المستدامه فضلا عن مبادراتها المشتركه في المنطقه الاقتصاديه الخاصه بالدقم لربط مخرجات البحث العلمي بقطاعات الصناعه والاقتصاد الازرق والطاقه المتجدده', 'cat-11-science-education', 'التعليم العالي والجامعات', 'vol-04', '["جامعة السلطان قابوس","التعليم العالي","البحث العلمي","مسقط","الخوض","مركز الدراسات العُمانية","1986"]'::jsonb, 'جامعه السلطان قابوس التعليم العالي البحث العلمي مسقط الخوض مركز الدراسات العمانيه 1986', 'هيئة تحرير الموسوعة (استناداً إلى جامعة السلطان قابوس والبوابة الإعلامية)', 'src-squ', 'https://www.squ.edu.om', '[{"title":"نبذة عن جامعة السلطان قابوس وكلياتها ومراكزها البحثية","url":"https://www.squ.edu.om","publisher":"جامعة السلطان قابوس","accessDate":"2026-10-16","sourceType":"academic_omani"},{"title":"التعليم والبحث العلمي في سلطنة عُمان — البوابة الإعلامية","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من جامعة السلطان قابوس والمصادر الرسمية', '[]'::jsonb, 'e309e48cc7d2dda76ed50b61c8e87672', 175, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-11-duqm-economic-zone', 'duqm-special-economic-zone-and-economy', 'المنطقة الاقتصادية الخاصة بالدقم: البوابة اللوجستية والصناعية على بحر العرب', 'المنطقه الاقتصاديه الخاصه بالدقم البوابه اللوجستيه والصناعيه علي بحر العرب', 'تقع المنطقة الاقتصادية الخاصة بالدقم في محافظة الوسطى على ساحل بحر العرب، وتُعد أحد أكبر المشاريع الاقتصادية واللوجستية والصناعية ومراكز الطاقة المتجددة في المنطقة.', 'تقع المنطقه الاقتصاديه الخاصه بالدقم في محافظه الوسطي علي ساحل بحر العرب وتعد احد اكبر المشاريع الاقتصاديه واللوجستيه والصناعيه ومراكز الطاقه المتجدده في المنطقه', 'تقع المنطقة الاقتصادية الخاصة بالدقم في ولاية الدقم بمحافظة الوسطى على الساحل الجنوبي الشرقي لسلطنة عُمان، مطلة مباشرة على بحر العرب والمحيط الهندي خارج مضيق هرمز، مما يمنحها موقعاً جغرافياً ولوجستياً استراتيجياً يربط خطوط الملاحة والتجارة العالمية بين آسيا وأفريقيا وأوروبا.

تُعد الدقم حجر الزاوية في استراتيجية التنويع الاقتصادي ضمن «رؤية عُمان 2040»، وتتكامل فيها منظومة بنية أساسية عملاقة تضم:
1. ميناء الدقم متعدد الأغراض: يتميز بأعماقه الكبيرة وأرصفته التجارية والنفطية وأرصفة المواد السائبة والحاويات.
2. الحوض الجاف لإصلاح وبناء السفن: يُعد من أكبر الأحواض الجافة في الشرق الأوسط لصيانة السفن العملاقة وناقلات النفط والغاز.
3. مصفاة الدقم والصناعات البتروكيماوية: مشروع استراتيجي مشترك يعزز القيمة المضافة لقطاع الطاقة والصناعات التحويلية.
4. منطقة الصناعات السمكية والغذائية: تستثمر الثروة السمكية الهائلة في بحر العرب لتعزيز الأمن الغذائي والتصدير.
5. مشاريع الهيدروجين الأخضر والطاقة المتجددة: بفضل وفرة الطاقة الشمسية وسرعة الرياح في محافظة الوسطى، أصبحت الدقم مركزاً رئيسياً لمشاريع إنتاج الهيدروجين الأخضر والأمونيا الخضراء والصناعات الخالية من الانبعاثات الكربونية.', 'تقع المنطقه الاقتصاديه الخاصه بالدقم في ولايه الدقم بمحافظه الوسطي علي الساحل الجنوبي الشرقي لسلطنه عمان مطله مباشره علي بحر العرب والمحيط الهندي خارج مضيق هرمز مما يمنحها موقعا جغرافيا ولوجستيا استراتيجيا يربط خطوط الملاحه والتجاره العالميه بين اسيا وافريقيا واوروبا تعد الدقم حجر الزاويه في استراتيجيه التنويع الاقتصادي ضمن رويه عمان 2040 وتتكامل فيها منظومه بنيه اساسيه عملاقه تضم 1 ميناء الدقم متعدد الاغراض يتميز باعماقه الكبيره وارصفته التجاريه والنفطيه وارصفه المواد السايبه والحاويات 2 الحوض الجاف لاصلاح وبناء السفن يعد من اكبر الاحواض الجافه في الشرق الاوسط لصيانه السفن العملاقه وناقلات النفط والغاز 3 مصفاه الدقم والصناعات البتروكيماويه مشروع استراتيجي مشترك يعزز القيمه المضافه لقطاع الطاقه والصناعات التحويليه 4 منطقه الصناعات السمكيه والغذاييه تستثمر الثروه السمكيه الهايله في بحر العرب لتعزيز الامن الغذايي والتصدير 5 مشاريع الهيدروجين الاخضر والطاقه المتجدده بفضل وفره الطاقه الشمسيه وسرعه الرياح في محافظه الوسطي اصبحت الدقم مركزا رييسيا لمشاريع انتاج الهيدروجين الاخضر والامونيا الخضراء والصناعات الخاليه من الانبعاثات الكربونيه', 'cat-12-economy-trade', 'المنطقة الاقتصادية الخاصة بالدقم', 'vol-06', '["المنطقة الاقتصادية الخاصة بالدقم","ميناء الدقم","الحوض الجاف","الاقتصاد العُماني","الهيدروجين الأخضر","محافظة الوسطى"]'::jsonb, 'المنطقه الاقتصاديه الخاصه بالدقم ميناء الدقم الحوض الجاف الاقتصاد العماني الهيدروجين الاخضر محافظه الوسطي', 'هيئة تحرير الموسوعة (استناداً إلى هيئة المناطق الاقتصادية الخاصة بالدقم)', 'src-duqm', 'https://www.duqm.gov.om', '[{"title":"المنطقة الاقتصادية الخاصة بالدقم — المكونات والمشاريع الاستراتيجية","url":"https://www.duqm.gov.om","publisher":"الهيئة العامة للمناطق الاقتصادية الخاصة والمناطق الحرة","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"الاقتصاد والتنويع الاقتصادي في سلطنة عُمان — البوابة الإعلامية","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المصادر الاقتصادية الرسمية العُمانية', '[]'::jsonb, '3e9c7506354c796bf8b9947db2f2113a', 184, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-12-arabian-oryx-reserve', 'arabian-oryx-reserve-and-biodiversity', 'محمية المها العربية وجهود صون الحياة الفطرية في سلطنة عُمان', 'محميه المها العربيه وجهود صون الحياه الفطريه في سلطنه عمان', 'تقع محمية الكائنات الحية والفطرية (محمية المها العربية) في محافظة الوسطى، وتُمثل أول محمية طبيعية في سلطنة عُمان وأيقونة عالمية لإعادة توطين المها العربي في بيئته الطبيعية.', 'تقع محميه الكاينات الحيه والفطريه محميه المها العربيه في محافظه الوسطي وتمثل اول محميه طبيعيه في سلطنه عمان وايقونه عالميه لاعاده توطين المها العربي في بييته الطبيعيه', 'تقع محمية الكائنات الحية والفطرية (المعروفة تاريخياً باسم «محمية المها العربية») في منطقة «وادي جعلوني» بصحراء جدة الحراسيس في محافظة الوسطى، وتُعد أول محمية طبيعية أُنشئت في سلطنة عُمان بهدف حماية النظم البيئية الصحراوية وإعادة توطين المها العربي في موطنه الأصلي بعد أن تعرض للانقراض في البرية في مطلع السبعينيات من القرن العشرين.

انطلق مشروع إعادة توطين المها العربي في سلطنة عُمان في مطلع الثمانينيات، وحظي بإشادة علمية دولية واسعة بوصفه أحد أنجح برامج استعادة الأنواع المهددة بالانقراض إلى بيئتها الطبيعية الفطرية. وإلى جانب قطعان المها العربي، تحتضن المحمية تنوعاً أحيائياً مهماً يشمل:
- الغزال العربي (الظبي) وغزال الريم (الغزال الرملي).
- الوعل النوبي في الجروف الصخرية الشرقية المطلة على بحر العرب.
- طائر الحبارى والوشق الصحراوي وثعلب الرمال.
- غطاءً نباتياً صحراوياً يعتمد على ظاهرة «الضباب الموسمي» القادم من بحر العرب، والذي يغذي أشجار الغاف والسمر والنباتات الرعوية النادرة.

وتُشرف هيئة البيئة بسلطنة عُمان على إدارة شبكة واسعة من المحميات الطبيعية البرية والبحرية المنتشرة في محافظات السلطنة، مثل محمية جبل سمحان (موطن النمر العربي في ظفار)، ومحمية السلاحف برأس الحد، ومحمية القرم الطبيعية في مسقط.', 'تقع محميه الكاينات الحيه والفطريه المعروفه تاريخيا باسم محميه المها العربيه في منطقه وادي جعلوني بصحراء جده الحراسيس في محافظه الوسطي وتعد اول محميه طبيعيه انشيت في سلطنه عمان بهدف حمايه النظم البيييه الصحراويه واعاده توطين المها العربي في موطنه الاصلي بعد ان تعرض للانقراض في البريه في مطلع السبعينيات من القرن العشرين انطلق مشروع اعاده توطين المها العربي في سلطنه عمان في مطلع الثمانينيات وحظي باشاده علميه دوليه واسعه بوصفه احد انجح برامج استعاده الانواع المهدده بالانقراض الي بييتها الطبيعيه الفطريه والي جانب قطعان المها العربي تحتضن المحميه تنوعا احياييا مهما يشمل الغزال العربي الظبي وغزال الريم الغزال الرملي الوعل النوبي في الجروف الصخريه الشرقيه المطله علي بحر العرب طاير الحباري والوشق الصحراوي وثعلب الرمال غطاء نباتيا صحراويا يعتمد علي ظاهره الضباب الموسمي القادم من بحر العرب والذي يغذي اشجار الغاف والسمر والنباتات الرعويه النادره وتشرف هييه البييه بسلطنه عمان علي اداره شبكه واسعه من المحميات الطبيعيه البريه والبحريه المنتشره في محافظات السلطنه مثل محميه جبل سمحان موطن النمر العربي في ظفار ومحميه السلاحف براس الحد ومحميه القرم الطبيعيه في مسقط', 'cat-13-environment-wildlife', 'المحميات الطبيعية البرية', 'vol-01', '["محمية المها العربية","المها العربي","وادي جعلوني","هيئة البيئة","الحياة الفطرية","جبل سمحان","محافظة الوسطى"]'::jsonb, 'محميه المها العربيه المها العربي وادي جعلوني هييه البييه الحياه الفطريه جبل سمحان محافظه الوسطي', 'هيئة تحرير الموسوعة (استناداً إلى هيئة البيئة والبوابة الإعلامية)', 'src-ea', 'https://www.ea.gov.om', '[{"title":"محمية الكائنات الحية والفطرية بمحافظة الوسطى — هيئة البيئة","url":"https://www.ea.gov.om","publisher":"هيئة البيئة بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"محمية المها العربية — البوابة الإعلامية لسلطنة عُمان","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من هيئة البيئة بسلطنة عُمان', '[]'::jsonb, 'a7f96db11e154ff958f512f13148b201', 168, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-13-frankincense-land-flora', 'omani-frankincense-tree-and-land-of-frankincense', 'شجرة اللبان العُماني ومواقع «أرض اللبان» في محافظة ظفار', 'شجره اللبان العماني ومواقع ارض اللبان في محافظه ظفار', 'تنمو شجرة اللبان العُماني الأصيلة (Boswellia sacra) في الأودية الجافة بمحافظة ظفار، وقد أدرجت اليونسكو مواقع «أرض اللبان» الأربعة في قائمة التراث العالمي عام 2000م.', 'تنمو شجره اللبان العماني الاصيله boswellia sacra في الاوديه الجافه بمحافظه ظفار وقد ادرجت اليونسكو مواقع ارض اللبان الاربعه في قايمه التراث العالمي عام 2000م', 'تُعد شجرة اللبان العُماني (الاسم العلمي: Boswellia sacra) من أشهر النباتات العطرية والطبية والتاريخية التي ارتبطت بحضارة عُمان منذ آلاف السنين. تنمو هذه الشجرة المعمرة طبيعياً في محافظة ظفار جنوب سلطنة عُمان، لا سيما في الأودية الجافة الواقعة في الظل المطري خلف سلسلة جبال ظفار حيث تتأثر بالرطوبة والرياح الموسمية دون هطول مطري غزير مباشر.

يُستخرج اللبان عبر عملية تقليدية دقيقة تُعرف محلياً بـ «التجريح» أو «الوقيع» في فصل الصيف؛ حيث يُحدث الحرفيون شقوقاً مدروسة في لحاء الشجرة بأداة «المنقف»، فيخرج سائل لبني يتجمد عند تعرضه للهواء مكوناً فصوص اللبان البلورية العطرية. ويُصنف اللبان الظفاري تقليدياً بحسب جودته وموعد حصاده ومنطقته الجغرافية إلى أربعة أصناف رئيسية يتقدمها «اللبان الحوجري» الفاخر ذو اللون الفاتح والنقاء العالي، يليه «النجدي»، و«الشزري»، و«الشعبي».

وفي عام 2000م، أدرجت منظمة اليونسكو مواقع «أرض اللبان» في محافظة ظفار ضمن قائمة التراث العالمي، وتضم أربعة مواقع متكاملة توثق زراعة اللبان وتجارته البحرية والبرية القديمة:
1. محمية وادي دوكة الطبيعية لأشجار اللبان.
2. بقايا واحة شصر (وبار) التي كانت نقطة انطلاق القوافل البرية عبر الصحراء.
3. ميناء خور روري (سمهرم) التاريخي.
4. موقع البليد الأثري في صلالة.', 'تعد شجره اللبان العماني الاسم العلمي boswellia sacra من اشهر النباتات العطريه والطبيه والتاريخيه التي ارتبطت بحضاره عمان منذ الاف السنين تنمو هذه الشجره المعمره طبيعيا في محافظه ظفار جنوب سلطنه عمان لا سيما في الاوديه الجافه الواقعه في الظل المطري خلف سلسله جبال ظفار حيث تتاثر بالرطوبه والرياح الموسميه دون هطول مطري غزير مباشر يستخرج اللبان عبر عمليه تقليديه دقيقه تعرف محليا ب التجريح او الوقيع في فصل الصيف حيث يحدث الحرفيون شقوقا مدروسه في لحاء الشجره باداه المنقف فيخرج سايل لبني يتجمد عند تعرضه للهواء مكونا فصوص اللبان البلوريه العطريه ويصنف اللبان الظفاري تقليديا بحسب جودته وموعد حصاده ومنطقته الجغرافيه الي اربعه اصناف رييسيه يتقدمها اللبان الحوجري الفاخر ذو اللون الفاتح والنقاء العالي يليه النجدي و الشزري و الشعبي وفي عام 2000م ادرجت منظمه اليونسكو مواقع ارض اللبان في محافظه ظفار ضمن قايمه التراث العالمي وتضم اربعه مواقع متكامله توثق زراعه اللبان وتجارته البحريه والبريه القديمه 1 محميه وادي دوكه الطبيعيه لاشجار اللبان 2 بقايا واحه شصر وبار التي كانت نقطه انطلاق القوافل البريه عبر الصحراء 3 ميناء خور روري سمهرم التاريخي 4 موقع البليد الاثري في صلاله', 'cat-14-flora-fauna', 'شجرة اللبان والنباتات العطرية', 'vol-01', '["شجرة اللبان","أرض اللبان","محافظة ظفار","وادي دوكة","سمهرم","البليد","اللبان الحوجري","اليونسكو"]'::jsonb, 'شجره اللبان ارض اللبان محافظه ظفار وادي دوكه سمهرم البليد اللبان الحوجري اليونسكو', 'هيئة تحرير الموسوعة (استناداً إلى اليونسكو ووزارة التراث والسياحة)', 'src-unesco-om', 'https://whc.unesco.org/ar/statesparties/om', '[{"title":"أرض اللبان في محافظة ظفار (إدراج عام 2000م) — مركز التراث العالمي","url":"https://whc.unesco.org/ar/statesparties/om","publisher":"منظمة اليونسكو (UNESCO)","accessDate":"2026-10-16","sourceType":"international"},{"title":"شجرة اللبان العُماني ومواقع التراث العالمي — البوابة الإعلامية","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من اليونسكو والمصادر العُمانية الرسمية', '[]'::jsonb, '4aac01a1931ae607fd00eb49e2b79ae1', 221, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-14-national-museum-oman', 'national-museum-of-the-sultanate-of-oman', 'المتحف الوطني بسلطنة عُمان: الصرح الحاضن لمكنونات التراث الحضاري', 'المتحف الوطني بسلطنه عمان الصرح الحاضن لمكنونات التراث الحضاري', 'يقع المتحف الوطني في قلب مدينة مسقط التاريخية مقابل قصر العلم العامر، ويضم 14 قاعة عرض دائمة توثق تاريخ عُمان منذ أقدم أثر بشري وحتى عصر النهضة المتجددة.', 'يقع المتحف الوطني في قلب مدينه مسقط التاريخيه مقابل قصر العلم العامر ويضم 14 قاعه عرض دايمه توثق تاريخ عمان منذ اقدم اثر بشري وحتي عصر النهضه المتجدده', 'أُسس المتحف الوطني بسلطنة عُمان بموجب المرسوم السلطاني رقم (62/2013) ليكون الصرح الثقافي الأعلى في السلطنة والمخصص لإبراز مكنونات التراث الثقافي العُماني المادي وغير المادي، منذ بداية ظهور الأثر البشري في شبه الجزيرة العُمانية قبل نحو مليوني عام وحتى العصر الحديث.

يقع مبنى المتحف الوطني في مدينة مسقط التاريخية مقابل قصر العلم العامر، ويحتوي على أربع عشرة (14) قاعة عرض دائمة مصممة وفق أحدث المعايير المتحفية العالمية، وهي:
- قاعة الأرض والإنسان.
- قاعة التاريخ البحري.
- قاعة السلاح.
- قاعة المنجز الحضاري.
- قاعة الأفلاج.
- قاعة العملات.
- قاعة الحقب الزمنية.
- قاعة بات والخطم والعين.
- قاعة أرض اللبان.
- قاعة ما قبل التاريخ والعصور القديمة (حضارة مجان).
- قاعة عظمة الإسلام.
- قاعة عُمان والعالم.
- قاعة عصر النهضة.
- قاعة التراث غير المادي.

كما يتميز المتحف الوطني بكونه أول متحف في منطقة الشرق الأوسط يعتمد منظومة «خط برايل» باللغة العربية للمكفوفين، ويضم مركزاً متكاملاً للحفظ والصون ومخازن مفتوحة تتيح للباحثين والدارسين الاطلاع على اللقى الأثرية والمخطوطات النادرة.', 'اسس المتحف الوطني بسلطنه عمان بموجب المرسوم السلطاني رقم 62 2013 ليكون الصرح الثقافي الاعلي في السلطنه والمخصص لابراز مكنونات التراث الثقافي العماني المادي وغير المادي منذ بدايه ظهور الاثر البشري في شبه الجزيره العمانيه قبل نحو مليوني عام وحتي العصر الحديث يقع مبني المتحف الوطني في مدينه مسقط التاريخيه مقابل قصر العلم العامر ويحتوي علي اربع عشره 14 قاعه عرض دايمه مصممه وفق احدث المعايير المتحفيه العالميه وهي قاعه الارض والانسان قاعه التاريخ البحري قاعه السلاح قاعه المنجز الحضاري قاعه الافلاج قاعه العملات قاعه الحقب الزمنيه قاعه بات والخطم والعين قاعه ارض اللبان قاعه ما قبل التاريخ والعصور القديمه حضاره مجان قاعه عظمه الاسلام قاعه عمان والعالم قاعه عصر النهضه قاعه التراث غير المادي كما يتميز المتحف الوطني بكونه اول متحف في منطقه الشرق الاوسط يعتمد منظومه خط برايل باللغه العربيه للمكفوفين ويضم مركزا متكاملا للحفظ والصون ومخازن مفتوحه تتيح للباحثين والدارسين الاطلاع علي اللقي الاثريه والمخطوطات النادره', 'cat-16-national-institutions', 'المتاحف الوطنية والصروح الثقافية', 'vol-05', '["المتحف الوطني","مسقط","قصر العلم","التراث العُماني","قاعة التاريخ البحري","المؤسسات الوطنية"]'::jsonb, 'المتحف الوطني مسقط قصر العلم التراث العماني قاعه التاريخ البحري الموسسات الوطنيه', 'هيئة تحرير الموسوعة (استناداً إلى المتحف الوطني العُماني)', 'src-national-museum', 'https://www.nm.gov.om', '[{"title":"حول المتحف الوطني وقاعاته الدائمة — الموقع الرسمي للمتحف الوطني","url":"https://www.nm.gov.om","publisher":"المتحف الوطني بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"cultural_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من المتحف الوطني بسلطنة عُمان', '[]'::jsonb, 'ad1bf2566f22825583612e8b0b5a02f6', 198, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-15-oman-vision-2040', 'oman-vision-2040-strategic-framework', 'رؤية عُمان 2040: المرتكزات الوطنية والأولويات التنموية لعُمان المعاصرة', 'رويه عمان 2040 المرتكزات الوطنيه والاولويات التنمويه لعمان المعاصره', 'تمثل «رؤية عُمان 2040» المرجعية الوطنية للتخطيط الاقتصادي والاجتماعي في سلطنة عُمان للعقدين (2021–2040م)، وتقوم على أربعة محاور رئيسية تشمل الإنسان والمجتمع، والاقتصاد والتنمية، والحوكمة، والبيئة.', 'تمثل رويه عمان 2040 المرجعيه الوطنيه للتخطيط الاقتصادي والاجتماعي في سلطنه عمان للعقدين 2021 2040م وتقوم علي اربعه محاور رييسيه تشمل الانسان والمجتمع والاقتصاد والتنميه والحوكمه والبييه', 'تُعد «رؤية عُمان 2040» البوصلة الوطنية والمرجعية الأساسية للتخطيط الاقتصادي والاجتماعي والتنموي في سلطنة عُمان خلال الفترة من عام 2021م إلى عام 2040م. أُعدت الرؤية بمشاركة مجتمعية ومؤسسية واسعة تحت شعار «نتقدم بثقة»، ودخلت حيز التنفيذ الفعلي مع انطلاق الخطة الخمسية العاشرة (2021–2025م) في مطلع عهد النهضة المتجددة بقيادة حضرة صاحب الجلالة السلطان هيثم بن طارق المعظم.

ترتكز رؤية عُمان 2040 على أربعة محاور استراتيجية كبرى تتفرع عنها اثنتا عشرة (12) أولوية وطنية:
1. محور الإنسان والمجتمع: ويشمل أولويات التعليم والتعلم والبحث العلمي والقدرات الوطنية، والصحة، والمواطنة والهوية والتراث والثقافة الوطنية، والرفاه والحماية الاجتماعية.
2. محور الاقتصاد والتنمية: ويشمل أولويات القيادة والإدارة الاقتصادية، والتنويع الاقتصادي والاستدامة المالية، وسوق العمل والتشغيل، والقطاع الخاص والاستثمار والتعاون الدولي، وتنمية المحافظات والمدن المستدامة.
3. محور الحوكمة والأداء المؤسسي: ويشمل أولويات التشريع والقضاء والرقابة، وحوكمة الجهاز الإداري للدولة والموارد والمشاريع.
4. محور البيئة المستدامة: ويشمل أولوية البيئة والموارد الطبيعية وأمن الطاقة والغذاء والمياه.

وتولي الرؤية اهتماماً خاصاً بتطبيق اللامركزية الإدارية وتمكين المحافظات الإحدى عشرة من استثمار ميزاتها النسبية والتنافسية لتحقيق تنمية متوازنة ومستدامة.', 'تعد رويه عمان 2040 البوصله الوطنيه والمرجعيه الاساسيه للتخطيط الاقتصادي والاجتماعي والتنموي في سلطنه عمان خلال الفتره من عام 2021م الي عام 2040م اعدت الرويه بمشاركه مجتمعيه وموسسيه واسعه تحت شعار نتقدم بثقه ودخلت حيز التنفيذ الفعلي مع انطلاق الخطه الخمسيه العاشره 2021 2025م في مطلع عهد النهضه المتجدده بقياده حضره صاحب الجلاله السلطان هيثم بن طارق المعظم ترتكز رويه عمان 2040 علي اربعه محاور استراتيجيه كبري تتفرع عنها اثنتا عشره 12 اولويه وطنيه 1 محور الانسان والمجتمع ويشمل اولويات التعليم والتعلم والبحث العلمي والقدرات الوطنيه والصحه والمواطنه والهويه والتراث والثقافه الوطنيه والرفاه والحمايه الاجتماعيه 2 محور الاقتصاد والتنميه ويشمل اولويات القياده والاداره الاقتصاديه والتنويع الاقتصادي والاستدامه الماليه وسوق العمل والتشغيل والقطاع الخاص والاستثمار والتعاون الدولي وتنميه المحافظات والمدن المستدامه 3 محور الحوكمه والاداء الموسسي ويشمل اولويات التشريع والقضاء والرقابه وحوكمه الجهاز الاداري للدوله والموارد والمشاريع 4 محور البييه المستدامه ويشمل اولويه البييه والموارد الطبيعيه وامن الطاقه والغذاء والمياه وتولي الرويه اهتماما خاصا بتطبيق اللامركزيه الاداريه وتمكين المحافظات الاحدي عشره من استثمار ميزاتها النسبيه والتنافسيه لتحقيق تنميه متوازنه ومستدامه', 'cat-17-modern-oman', 'رؤية عُمان 2040', 'vol-06', '["رؤية عُمان 2040","النهضة المتجددة","التنويع الاقتصادي","تنمية المحافظات","الحوكمة","التنمية المستدامة"]'::jsonb, 'رويه عمان 2040 النهضه المتجدده التنويع الاقتصادي تنميه المحافظات الحوكمه التنميه المستدامه', 'هيئة تحرير الموسوعة (استناداً إلى وحدة متابعة تنفيذ رؤية عُمان 2040)', 'src-oman2040', 'https://www.oman2040.om', '[{"title":"وثيقة رؤية عُمان 2040 — المحاور والأولويات الوطنية","url":"https://www.oman2040.om","publisher":"وحدة متابعة تنفيذ رؤية عُمان 2040","accessDate":"2026-10-16","sourceType":"official_omani"},{"title":"رؤية عُمان 2040 واللامركزية الإدارية — البوابة الإعلامية","url":"https://www.omaninfo.om","publisher":"وزارة الإعلام بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'صياغة موسوعية أصلية موثقة من وثيقة رؤية عُمان 2040 الرسمية', '[]'::jsonb, '26cf2d35932fdd3034e6f2b2458506b1', 315, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-16-magan-and-qalhat-archaeology', 'magan-civilization-bat-and-ancient-qalhat', 'حضارة مجان ومواقع بات والخطم والعين ومدينة قلهات الأثرية', 'حضاره مجان ومواقع بات والخطم والعين ومدينه قلهات الاثريه', 'عُرفت عُمان في النصوص الرافدينية القديمة باسم «مجان» بوصفها مصدراً رئيسياً للنحاس واللبان في الألف الثالث قبل الميلاد، وتبرز آثارها في بات والخطم والعين ومدينة قلهات التاريخية.', 'عرفت عمان في النصوص الرافدينيه القديمه باسم مجان بوصفها مصدرا رييسيا للنحاس واللبان في الالف الثالث قبل الميلاد وتبرز اثارها في بات والخطم والعين ومدينه قلهات التاريخيه', 'يمتد التاريخ الحضاري لعُمان إلى عصور ما قبل التاريخ؛ حيث عُرفت شبه الجزيرة العُمانية في الرقم الطينية السومرية والأكدية في بلاد الرافدين خلال الألف الثالث قبل الميلاد باسم «مجان» (Magan)، واشتهرت بكونها المصدر الرئيسي لتعدين وصهر النحاس وتصديره بحراً عبر الخليج العربي ومروراً بـ «دلمون» وحضارة وادي السند (ملوخا)، فضلاً عن صناعة السفن الحجرية والخشبية وتجارة حجر الديورايت واللبان.

أولاً: مواقع بات والخطم والعين الأثرية (محافظة الظاهرة)
تقع هذه المستوطنات والمدافن الأثرية في ولاية عبري بمحافظة الظاهرة، وتُعد من أكمل تجمعات الأبراج والمدافن الحجرية الدائرية («خلايا النحل» ومدافن أم النار) في العالم من الألف الثالث قبل الميلاد. وقد أُدرجت مواقع بات والخطم والعين في قائمة التراث العالمي لليونسكو عام 1988م.

ثانياً: مدينة قلهات الأثرية والروايات التاريخية حولها
تقع مدينة قلهات التاريخية على ساحل بحر عُمان في ولاية صور بمحافظة جنوب الشرقية، وأُدرجت في قائمة التراث العالمي لليونسكو عام 2018م. ازدهرت قلهات بوصفها ميناءً رئيسياً لمملكة هرمز وعُمان بين القرنين الحادي عشر والسادس عشر الميلاديين، وزارها الرحالة مثل ماركو بولو وابن بطوطة، ولا يزال «ضريح بيبي مريم» شاهداً معمارياً بارزاً فيها.
تنبيه منهجي حول الروايات التاريخية: تتفق المصادر الأثرية والتاريخية المؤكدة على ازدهار قلهات التجاري وتعرضها للدمار في مطلع القرن السادس عشر الميلادي (نحو عام 1508م على يد الأسطول البرتغالي بقيادة ألفونسو دي ألبوكيرك)، بينما تتباين بعض الروايات الإخبارية المتأخرة في تقدير حجم الزلزال الذي قيل إنه أصاب المدينة قبل ذلك أو بعده، ولذلك تفصل الدراسات الأثرية الحديثة بين الشواهد المادية المؤكدة والروايات الإخبارية المختلف في تفاصيلها.', 'يمتد التاريخ الحضاري لعمان الي عصور ما قبل التاريخ حيث عرفت شبه الجزيره العمانيه في الرقم الطينيه السومريه والاكديه في بلاد الرافدين خلال الالف الثالث قبل الميلاد باسم مجان magan واشتهرت بكونها المصدر الرييسي لتعدين وصهر النحاس وتصديره بحرا عبر الخليج العربي ومرورا ب دلمون وحضاره وادي السند ملوخا فضلا عن صناعه السفن الحجريه والخشبيه وتجاره حجر الديورايت واللبان اولا مواقع بات والخطم والعين الاثريه محافظه الظاهره تقع هذه المستوطنات والمدافن الاثريه في ولايه عبري بمحافظه الظاهره وتعد من اكمل تجمعات الابراج والمدافن الحجريه الدايريه خلايا النحل ومدافن ام النار في العالم من الالف الثالث قبل الميلاد وقد ادرجت مواقع بات والخطم والعين في قايمه التراث العالمي لليونسكو عام 1988م ثانيا مدينه قلهات الاثريه والروايات التاريخيه حولها تقع مدينه قلهات التاريخيه علي ساحل بحر عمان في ولايه صور بمحافظه جنوب الشرقيه وادرجت في قايمه التراث العالمي لليونسكو عام 2018م ازدهرت قلهات بوصفها ميناء رييسيا لمملكه هرمز وعمان بين القرنين الحادي عشر والسادس عشر الميلاديين وزارها الرحاله مثل ماركو بولو وابن بطوطه ولا يزال ضريح بيبي مريم شاهدا معماريا بارزا فيها تنبيه منهجي حول الروايات التاريخيه تتفق المصادر الاثريه والتاريخيه الموكده علي ازدهار قلهات التجاري وتعرضها للدمار في مطلع القرن السادس عشر الميلادي نحو عام 1508م علي يد الاسطول البرتغالي بقياده الفونسو دي البوكيرك بينما تتباين بعض الروايات الاخباريه المتاخره في تقدير حجم الزلزال الذي قيل انه اصاب المدينه قبل ذلك او بعده ولذلك تفصل الدراسات الاثريه الحديثه بين الشواهد الماديه الموكده والروايات الاخباريه المختلف في تفاصيلها', 'cat-01-history-civilization', 'حضارة مجان والنحاس', 'vol-02', '["حضارة مجان","بات والخطم والعين","مدينة قلهات","بيبي مريم","النحاس العُماني","التراث العالمي","اليونسكو"]'::jsonb, 'حضاره مجان بات والخطم والعين مدينه قلهات بيبي مريم النحاس العماني التراث العالمي اليونسكو', 'هيئة تحرير الموسوعة (استناداً إلى اليونسكو والمتحف الوطني العُماني)', 'src-unesco-om', 'https://whc.unesco.org/ar/statesparties/om', '[{"title":"المواقع الأثرية في بات والخطم والعين (1988م) ومدينة قلهات (2018م) — اليونسكو","url":"https://whc.unesco.org/ar/statesparties/om","publisher":"منظمة اليونسكو (UNESCO)","accessDate":"2026-10-16","sourceType":"international"},{"title":"قاعة ما قبل التاريخ والعصور القديمة (حضارة مجان) — المتحف الوطني","url":"https://www.nm.gov.om","publisher":"المتحف الوطني بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"cultural_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'historical_narrative', 'صياغة موسوعية أصلية مع التمييز المنهجي بين الشواهد الأثرية والروايات التاريخية', '[]'::jsonb, '27b27657713022f369513a2c7dd7508f', 245, '2026-10-16T07:00:00Z', '2026-10-16T07:00:00Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-17-dhofar-khareef-review-draft', 'dhofar-khareef-monsoon-season-draft', 'موسم خريف ظفار: الظاهرة المناخية الموسمية والسياحة البيئية', 'موسم خريف ظفار الظاهره المناخيه الموسميه والسياحه البيييه', 'مقال قيد المراجعة العلمية حول الظاهرة المناخية الموسمية التي تشهدها محافظة ظفار سنوياً بين شهري يونيو وسبتمبر نتيجة الرياح الموسمية الجنوبية الغربية.', 'مقال قيد المراجعه العلميه حول الظاهره المناخيه الموسميه التي تشهدها محافظه ظفار سنويا بين شهري يونيو وسبتمبر نتيجه الرياح الموسميه الجنوبيه الغربيه', 'يشهد الشريط الساحلي والجبال المطلة عليه في محافظة ظفار جنوب سلطنة عُمان ظاهرة مناخية فريدة في شبه الجزيرة العربية تُعرف بـ «موسم الخريف»، وتبدأ فلكياً في 21 يونيو وتستمر حتى 21 سبتمبر من كل عام.

تحدث هذه الظاهرة نتيجة هبوب الرياح الموسمية الجنوبية الغربية القادمة من المحيط الهندي وبحر العرب، ما يؤدي إلى تكاثف السحب المنخفضة والضباب وهطول الرذاذ والأمطار الخفيفة المستمرة، وانخفاض درجات الحرارة لتتحول جبال وسهول ظفار (في ولايات صلالة وطاقة ومرباط ورخيوت وضلكوت وصرفيت) إلى بساط أخضر وتتدفق العيون والشلالات المائية مثل دربات وأثوم وطبرق وعين رزات وعين جرزيز.

ملاحظة تحريرية: هذا المقال مخصص في قاعدة البيانات بحالة «قيد المراجعة» لإتاحة اختبار دورة المراجعة التحريرية والاعتماد من لوحة الإدارة قبل النشر النهائي.', 'يشهد الشريط الساحلي والجبال المطله عليه في محافظه ظفار جنوب سلطنه عمان ظاهره مناخيه فريده في شبه الجزيره العربيه تعرف ب موسم الخريف وتبدا فلكيا في 21 يونيو وتستمر حتي 21 سبتمبر من كل عام تحدث هذه الظاهره نتيجه هبوب الرياح الموسميه الجنوبيه الغربيه القادمه من المحيط الهندي وبحر العرب ما يودي الي تكاثف السحب المنخفضه والضباب وهطول الرذاذ والامطار الخفيفه المستمره وانخفاض درجات الحراره لتتحول جبال وسهول ظفار في ولايات صلاله وطاقه ومرباط ورخيوت وضلكوت وصرفيت الي بساط اخضر وتتدفق العيون والشلالات الماييه مثل دربات واثوم وطبرق وعين رزات وعين جرزيز ملاحظه تحريريه هذا المقال مخصص في قاعده البيانات بحاله قيد المراجعه لاتاحه اختبار دوره المراجعه التحريريه والاعتماد من لوحه الاداره قبل النشر النهايي', 'cat-15-tourism-nature', 'موسم خريف ظفار', 'vol-01', '["خريف ظفار","صلالة","وادي دربات","السياحة البيئية","محافظة ظفار","الرياح الموسمية"]'::jsonb, 'خريف ظفار صلاله وادي دربات السياحه البيييه محافظه ظفار الرياح الموسميه', 'وحدة الاستيراد والمراجعة التحريرية', 'src-mht', 'https://mht.gov.om', '[{"title":"موسم خريف ظفار والمقومات السياحية — وزارة التراث والسياحة","url":"https://mht.gov.om","publisher":"وزارة التراث والسياحة بسلطنة عُمان","accessDate":"2026-10-16","sourceType":"official_omani"}]'::jsonb, '2026-10-16', '2026-10-16', 'published', 'confirmed_fact', 'مسودة موسوعية قيد المراجعة التحريرية', '[]'::jsonb, '6c0a506ff9b15febea331ce76e5d38cf', 19, '2026-10-16T07:00:00Z', '2026-10-16T12:41:07.426Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-29fa9e04a5', 'سلطنة-عمان-04a5', 'سلطنة عمان', 'سلطنه عمان', 'عُمان (رسميًا: سَلْطَنَةُ عُمَان)، هي دولة عربية خليجية تقع في غرب آسيا في الربع الجنوبي الشرقي من شبه الجزيرة العربية. تقع بين خطي عرض 16° 40'' و 20'' 26° شمالًا وبين خطي طول 50'' 51°و 40'' °59 شرقًا.', 'عمان رسميا سلطنه عمان هي دوله عربيه خليجيه تقع في غرب اسيا في الربع الجنوبي الشرقي من شبه الجزيره العربيه تقع بين خطي عرض 16 40 و 20 26 شمالا وبين خطي طول 50 51 و 40 59 شرقا', 'عُمان (رسميًا: سَلْطَنَةُ عُمَان)، هي دولة عربية خليجية تقع في غرب آسيا في الربع الجنوبي الشرقي من شبه الجزيرة العربية. تقع بين خطي عرض 16° 40'' و 20'' 26° شمالًا وبين خطي طول 50'' 51°و 40'' °59 شرقًا. يحدها من الشمال الخليج العربي ومضيق هرمز ومن الشمال الغربي الإمارات ومن الغرب السعودية ومن الجنوب اليمن ومن الجنوب الشرقي بحر العرب. تغطي مساحة إجمالية تبلغ 309.500 كم² وهي بذلك تحتل المرتبة الثالثة من حيث المساحة في شبه الجزيرة العربية.
تمتد سواحلها على مسافة 3165 كلم من مضيق هرمز في الشمال وحتى الحدود مع اليمن، وتطل بذلك على بحار ثلاثة هي: بحر العرب، بحر عُمان، والخليج العربي. يبلغ طول حدودها المشتركة مع دولة الإمارات العربية المتحدة (410 كم) ومع المملكة العربية السعودية (676 كم)، ومع الجمهورية اليمنية (288 كم).
نظام الحكم في عُمان سلطاني وراثي والسلطان الحالي هو هيثم بن طارق آل سعيد الذي تولّى الحكم في 11 يناير 2020 عقب وفاة السلطان قابوس بن سعيد بن تيمور آل سعيد صاحب أطول فترة حكم في الشرق الأوسط حتى وفاته. لا يسمح الدستور العُماني بالأحزاب السياسية بينما يكفل حق الانتخاب لكل مواطن عُماني بلغ الواحدة والعشرين من عمره لاختيار أعضاء مجلس الشورى.
من أواخر القرن 15 كانت سلطنة عُمان إمبراطورية قوية تتنافس مع المملكة المتحدة والبرتغال على النفوذ في منطقة الخليج العربي والمحيط الهندي وذروتها  في القرن 19، النفوذ العُماني وسيطرته التي تمتد عبر مضيق باب السلام إلى العصر الحديث الإمارات وباكستان وإيران وجنوبًا حتى زنجبار كما انخفضت قوتها في القرن 20 جاءت السلطنة تحت تأثير المملكة المتحدة وتاريخيًّا كانت مسقط الميناء التجاري الرئيسي في منطقة الخليج العربي، مسقط كانت أيضًا من بين أهم الموانئ التجارية في المحيط الهندي.
يعتقد أن مجان الواردة في الكتابات السومرية تشير إلى عُمان الغالب أن عُمان كانت محطة وصل مهمة للقوافل التجارية وعرفت هذه المنطقة التاريخية باسم جبل النحاس ولها ارتباط بثقافة أم النار وصلات تجارية مع بلاد الرافدين ولا يعرف الكثير عن طبيعة النظم في تلك المستوطنات الصغيرة واختفت مجان من النصوص السومرية مبكراً في العام 1800 عام قبل الميلاد. تمتلك عُمان أربعة مواقع ضمن مواقع التراث العالمي وصنفت رقصة البرعة ضمن التراث الثقافي اللامادي للإنسانية واختيرت عدة مرات كوجهة سياحية لتاريخ البلاد وثقافتها وتنوع تضاريسها الجغرافية.
تتمتع سلطنة عُمان بوضع سياسي واقتصادي مستقر في العموم، اقتصادها نفطي إذ تحتل المرتبة 23 في احتياطي النفط على مستوى العالم والمرتبة 27 في احتياطي للغاز، والمرتبة 64 من بين أكبر اقتصادات العالم في عام 2010م. صنف برنامج الأمم المتحدة الإنمائي عُمان باعتبارها البلد الأكثر تحسنًا على مستوى العالم في مجال التنمية خلال 47 عامًا السابقة. تصنف عُمان كاقتصاد ذات الدخل المرتفع وتصنف باعتبارها الـ59 البلد الأكثر سلمية في العالم وفقًا لمؤشر السلام العالمي.
سلطنة عُمان عضو مؤسس في مجلس التعاون لدول الخليج العربية وحركة عدم الانحياز والبنك الإسلامي للتنمية وجامعة الدول العربية والأمم المتحدة ومنظمة المؤتمر الإسلامي ومنظمة التجارة العالمية والمنظمة الدولية للمعايير والوكالة الدولية للطاقة المتجددة والمنظمة الإسلامية للتربية والعلوم والثقافة.


== أصل التسمية ==
عُرفت عمان في المراحل التاريخية المختلفة بأكثر من اسم من أبرز أسمائها (أرض مجان ومزون وسلطنة عمان) حيث يرتبط كل منها ببعد حضاري أو تاريخي محدد، فاسم مجان ارتبط بما اشتهرت به من صناعة السفن وصهر النحاس حسب لغة السومريين حيث كانت تربطهم بعمان صلات تجارية وبحرية عديدة، وكان السومريون يطلقون عليها في لوحاتهم أرض مجان، أما اسم مزون فقد ارتبط بوفرة الموارد المائية في عمان في فترات تاريخية سابقة، وذلك بالقياس إلى البلدان العربية المجاورة لها، وكلمة مزون مشتقة من كلمة (المزن) وهي السحاب ذو الماء الغزير المتدفق ولعل هذا يفسر قيام وازدهار الزراعة في عمان منذ القدم وما صاحبها من حضارة أيضًا، أما بالنسبة لاسم عمان فقد ورد في هجرة القبائل العربية من مكان يطلق عليه عُمان في اليمن، كما قيل إنها سميت بعُمان نسبة إلى عُمان بن إبراهيم الخليل عليه السلام وقيل أنها سميت بهذا الاسم نسبة إلى عُمان بن سبأ بن يغثان بن إبراهيم. كانت عمان في القديم موطنًا للقبائل العربية التي قدمت إليها وسكن بعضها السهول واشتغلت بالزراعة والصيد واستقر البعض الآخر في المناطق الداخلية والصحراوية واشتغلت بالرعي وتربية الماشية.
في العصور الوسطى كان اسم عمان يطلق على كل ذلك الجزء من الجزيرة العربية الذي يقع شرقي قطر ثم جنوبًا إلى المحيط الهندي، ولكن بدءًا من القرن الثامن عشر كان هذا الاسم يطلق على الزاوية الجنوبية الشرقية من شبه الجزيرة العربية والتي تشكل اليوم سلطنة عمان والساحل المهادن.


== التاريخ ==


=== ما قبل التاريخ ===
اختلفت الآراء في أصل تسمية عمان فالبعض يرجعه إلى قبيلة عُمان القحطانية والبعض يأخذه من معنى الاستقرار والإقامة، يقول ابن الإعرابي: المعن أي المقيمون في مكان، يقال رجل عمان وعمون ومنه اشتقت كلمة عُمان، ويستطرد فيقول: أعمن الرجل أي دام على المقام بعمان أما الزجاجي فيقول: أن عمان سميت باسم عُمان بن إبراهيم الخليل عليه السلام بينما يذكر ابن الكلبي: أنها سميت باسم عُمان بن سبأ بن يغثان بن إبراهيم خليل الرحمن لأنه هو الذي بنى مدينة عُمان، أما شيخ الربوة فيقول: أنها سميت بهذا الاسم نسبة إلى عُمان بن لوط النبي عليه السلام.
وقيل أن الأزدي سمت عمان (عُمانا) لأن منازلهم كانت على واد لهم بمأرب يقال له عمان فشبهوها به ومن أقدم المؤرخين الرومان الذين ذكروا عُمان بهذا الاسم لينوس الذي عاش في القرن الأول للميلاد 23 م – 79 م فقد ورد في كتاباته اسم مدينة تسمى عمان (OMANA) وكذلك ورد هذا الاسم عند بطليموس الذي عاش في القرن الثاني للميلاد ويظن جروهمان أن عمان المذكورة عند هذين المؤرخين هي صحار التي كانت تعد المركز الاقتصادي الأكثر أهمية في المنطقة في العصر الكلاسيكي وقد عرفت عمان بأسماء أخرى فقد أطلق عليها السومريون ودول بلاد ما بين النهرين اسم مجان ربما نسبة إلى صناعة السفن التي تشتهر بها عمان، حيث ورد في النقوش المسمارية بأن مجان تعني هيكل السفينة كما سماها الفرس باسم مزون وورد اسم عمان في المصادر العربية على أنها إقليم مستقل.
في جنوب سلطنة عُمان تقع مدينة تعرف بظفار ويعود تسميتها إلى عصور قديمة فقد ورد ذكر ظفار في أحاديث روتها أم المؤمنين السيدة عائشة بنت أبي بكر رضى الله عنهما وتم اكتشاف موقع أثري في عام 2011م يحتوي على أكثر من 100 قطعة من الأدوات الحجرية وكذلك تم اكتشاف مواقع أثرية كالبليد وسمهرم وهو موقع أثري مشهور حيث كانت السفن تنقل اللبان لظفاري منه إلى جميع أنحاء العالم وقد ورد ذكر ظفار في المنحوتات الفرعونية زمن الملكة حتشبسوت فقد كان ينقل إليها اللبان لظفاري ليتم حرقة في المعابد الفرعونية.
في مدينة عبري، هو أقدم المستوطنات البشرية المعروفة في المنطقة، التي يعود تاريخها ما يصل إلى 8000 عام إلى أواخر العصر الحجري تم اكتشاف. البقايا الأثرية هنا من العصر الحجري والعصر ا', 'عمان رسميا سلطنه عمان هي دوله عربيه خليجيه تقع في غرب اسيا في الربع الجنوبي الشرقي من شبه الجزيره العربيه تقع بين خطي عرض 16 40 و 20 26 شمالا وبين خطي طول 50 51 و 40 59 شرقا يحدها من الشمال الخليج العربي ومضيق هرمز ومن الشمال الغربي الامارات ومن الغرب السعوديه ومن الجنوب اليمن ومن الجنوب الشرقي بحر العرب تغطي مساحه اجماليه تبلغ 309 500 كم² وهي بذلك تحتل المرتبه الثالثه من حيث المساحه في شبه الجزيره العربيه تمتد سواحلها علي مسافه 3165 كلم من مضيق هرمز في الشمال وحتي الحدود مع اليمن وتطل بذلك علي بحار ثلاثه هي بحر العرب بحر عمان والخليج العربي يبلغ طول حدودها المشتركه مع دوله الامارات العربيه المتحده 410 كم ومع المملكه العربيه السعوديه 676 كم ومع الجمهوريه اليمنيه 288 كم نظام الحكم في عمان سلطاني وراثي والسلطان الحالي هو هيثم بن طارق ال سعيد الذي تولي الحكم في 11 يناير 2020 عقب وفاه السلطان قابوس بن سعيد بن تيمور ال سعيد صاحب اطول فتره حكم في الشرق الاوسط حتي وفاته لا يسمح الدستور العماني بالاحزاب السياسيه بينما يكفل حق الانتخاب لكل مواطن عماني بلغ الواحده والعشرين من عمره لاختيار اعضاء مجلس الشوري من اواخر القرن 15 كانت سلطنه عمان امبراطوريه قويه تتنافس مع المملكه المتحده والبرتغال علي النفوذ في منطقه الخليج العربي والمحيط الهندي وذروتها في القرن 19 النفوذ العماني وسيطرته التي تمتد عبر مضيق باب السلام الي العصر الحديث الامارات وباكستان وايران وجنوبا حتي زنجبار كما انخفضت قوتها في القرن 20 جاءت السلطنه تحت تاثير المملكه المتحده وتاريخيا كانت مسقط الميناء التجاري الرييسي في منطقه الخليج العربي مسقط كانت ايضا من بين اهم المواني التجاريه في المحيط الهندي يعتقد ان مجان الوارده في الكتابات السومريه تشير الي عمان الغالب ان عمان كانت محطه وصل مهمه للقوافل التجاريه وعرفت هذه المنطقه التاريخيه باسم جبل النحاس ولها ارتباط بثقافه ام النار وصلات تجاريه مع بلاد الرافدين ولا يعرف الكثير عن طبيعه النظم في تلك المستوطنات الصغيره واختفت مجان من النصوص السومريه مبكرا في العام 1800 عام قبل الميلاد تمتلك عمان اربعه مواقع ضمن مواقع التراث العالمي وصنفت رقصه البرعه ضمن التراث الثقافي اللامادي للانسانيه واختيرت عده مرات كوجهه سياحيه لتاريخ البلاد وثقافتها وتنوع تضاريسها الجغرافيه تتمتع سلطنه عمان بوضع سياسي واقتصادي مستقر في العموم اقتصادها نفطي اذ تحتل المرتبه 23 في احتياطي النفط علي مستوي العالم والمرتبه 27 في احتياطي للغاز والمرتبه 64 من بين اكبر اقتصادات العالم في عام 2010م صنف برنامج الامم المتحده الانمايي عمان باعتبارها البلد الاكثر تحسنا علي مستوي العالم في مجال التنميه خلال 47 عاما السابقه تصنف عمان كاقتصاد ذات الدخل المرتفع وتصنف باعتبارها ال59 البلد الاكثر سلميه في العالم وفقا لموشر السلام العالمي سلطنه عمان عضو موسس في مجلس التعاون لدول الخليج العربيه وحركه عدم الانحياز والبنك الاسلامي للتنميه وجامعه الدول العربيه والامم المتحده ومنظمه الموتمر الاسلامي ومنظمه التجاره العالميه والمنظمه الدوليه للمعايير والوكاله الدوليه للطاقه المتجدده والمنظمه الاسلاميه للتربيه والعلوم والثقافه اصل التسميه عرفت عمان في المراحل التاريخيه المختلفه باكثر من اسم من ابرز اسمايها ارض مجان ومزون وسلطنه عمان حيث يرتبط كل منها ببعد حضاري او تاريخي محدد فاسم مجان ارتبط بما اشتهرت به من صناعه السفن وصهر النحاس حسب لغه السومريين حيث كانت تربطهم بعمان صلات تجاريه وبحريه عديده وكان السومريون يطلقون عليها في لوحاتهم ارض مجان اما اسم مزون فقد ارتبط بوفره الموارد الماييه في عمان في فترات تاريخيه سابقه وذلك بالقياس الي البلدان العربيه المجاوره لها وكلمه مزون مشتقه من كلمه المزن وهي السحاب ذو الماء الغزير المتدفق ولعل هذا يفسر قيام وازدهار الزراعه في عمان منذ القدم وما صاحبها من حضاره ايضا اما بالنسبه لاسم عمان فقد ورد في هجره القبايل العربيه من مكان يطلق عليه عمان في اليمن كما قيل انها سميت بعمان نسبه الي عمان بن ابراهيم الخليل عليه السلام وقيل انها سميت بهذا الاسم نسبه الي عمان بن سبا بن يغثان بن ابراهيم كانت عمان في القديم موطنا للقبايل العربيه التي قدمت اليها وسكن بعضها السهول واشتغلت بالزراعه والصيد واستقر البعض الاخر في المناطق الداخليه والصحراويه واشتغلت بالرعي وتربيه الماشيه في العصور الوسطي كان اسم عمان يطلق علي كل ذلك الجزء من الجزيره العربيه الذي يقع شرقي قطر ثم جنوبا الي المحيط الهندي ولكن بدءا من القرن الثامن عشر كان هذا الاسم يطلق علي الزاويه الجنوبيه الشرقيه من شبه الجزيره العربيه والتي تشكل اليوم سلطنه عمان والساحل المهادن التاريخ ما قبل التاريخ اختلفت الاراء في اصل تسميه عمان فالبعض يرجعه الي قبيله عمان القحطانيه والبعض ياخذه من معني الاستقرار والاقامه يقول ابن الاعرابي المعن اي المقيمون في مكان يقال رجل عمان وعمون ومنه اشتقت كلمه عمان ويستطرد فيقول اعمن الرجل اي دام علي المقام بعمان اما الزجاجي فيقول ان عمان سميت باسم عمان بن ابراهيم الخليل عليه السلام بينما يذكر ابن الكلبي انها سميت باسم عمان بن سبا بن يغثان بن ابراهيم خليل الرحمن لانه هو الذي بني مدينه عمان اما شيخ الربوه فيقول انها سميت بهذا الاسم نسبه الي عمان بن لوط النبي عليه السلام وقيل ان الازدي سمت عمان عمانا لان منازلهم كانت علي واد لهم بمارب يقال له عمان فشبهوها به ومن اقدم المورخين الرومان الذين ذكروا عمان بهذا الاسم لينوس الذي عاش في القرن الاول للميلاد 23 م 79 م فقد ورد في كتاباته اسم مدينه تسمي عمان omana وكذلك ورد هذا الاسم عند بطليموس الذي عاش في القرن الثاني للميلاد ويظن جروهمان ان عمان المذكوره عند هذين المورخين هي صحار التي كانت تعد المركز الاقتصادي الاكثر اهميه في المنطقه في العصر الكلاسيكي وقد عرفت عمان باسماء اخري فقد اطلق عليها السومريون ودول بلاد ما بين النهرين اسم مجان ربما نسبه الي صناعه السفن التي تشتهر بها عمان حيث ورد في النقوش المسماريه بان مجان تعني هيكل السفينه كما سماها الفرس باسم مزون وورد اسم عمان في المصادر العربيه علي انها اقليم مستقل في جنوب سلطنه عمان تقع مدينه تعرف بظفار ويعود تسميتها الي عصور قديمه فقد ورد ذكر ظفار في احاديث روتها ام المومنين السيده عايشه بنت ابي بكر رضي الله عنهما وتم اكتشاف موقع اثري في عام 2011م يحتوي علي اكثر من 100 قطعه من الادوات الحجريه وكذلك تم اكتشاف مواقع اثريه كالبليد وسمهرم وهو موقع اثري مشهور حيث كانت السفن تنقل اللبان لظفاري منه الي جميع انحاء العالم وقد ورد ذكر ظفار في المنحوتات الفرعونيه زمن الملكه حتشبسوت فقد كان ينقل اليها اللبان لظفاري ليتم حرقه في المعابد الفرعونيه في مدينه عبري هو اقدم المستوطنات البشريه المعروفه في المنطقه التي يعود تاريخها ما يصل الي 8000 عام الي اواخر العصر الحجري تم اكتشاف البقايا الاثريه هنا من العصر الحجري والعصر ا', 'cat-02-governorates', 'المحافظات والولايات الإدارية', 'vol-01', '["السلطان","قابوس بن سعيد","هيثم بن طارق","عالم","مؤرخ","مسقط","ظفار","صحار"]'::jsonb, 'السلطان قابوس بن سعيد هيثم بن طارق عالم مورخ مسقط ظفار صحار', 'الموسوعة الحرة (مرخصة تحت المشاع الإبداعي CC BY-SA 4.0 — مصدر دولي مفتوح)', 'src-79ee3163', 'https://ar.wikipedia.org/wiki/%D8%B3%D9%84%D8%B7%D9%86%D8%A9_%D8%B9%D9%85%D8%A7%D9%86', '[{"title":"سلطنة عمان","url":"https://ar.wikipedia.org/wiki/%D8%B3%D9%84%D8%B7%D9%86%D8%A9_%D8%B9%D9%85%D8%A7%D9%86","publisher":"الموسوعة الحرة (مرخصة تحت المشاع الإبداعي CC BY-SA 4.0 — مصدر دولي مفتوح)","accessDate":"2026-10-16","sourceType":"international"}]'::jsonb, '2026-10-15', '2026-10-16', 'published', 'confirmed_fact', 'Creative Commons Attribution-ShareAlike 4.0 (CC BY-SA 4.0) مع الإحالة للرابط الأصلي', '[]'::jsonb, 'cdf4e0facda33f27796e5f1c41828e25', 1, '2026-10-16T10:41:11.401Z', '2026-10-16T11:23:06.859Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-3837005593', 'تاريخ-سلطنة-عمان-5593', 'تاريخ سلطنة عمان', 'تاريخ سلطنه عمان', 'يمتد تاريخ عمان الحديث والمعاصر من مملكة النباهنة وحتى يومنا هذا، حيث بدأت مع وصول المستكشفين البرتغاليين إلى الشرق ومن ثم سيطرتهم على الهند والخليج العربي وشرق أفريقيا. كان للنشاط البحري العماني دوراً مهماً في توسيع التجارة الخارجية مع شرق آسيا حيث امتلكت عمان أسطولاً بحرياً ضخماً مكنها من بسط سيطرتها على الخليج وح...', 'يمتد تاريخ عمان الحديث والمعاصر من مملكه النباهنه وحتي يومنا هذا حيث بدات مع وصول المستكشفين البرتغاليين الي الشرق ومن ثم سيطرتهم علي الهند والخليج العربي وشرق افريقيا كان للنشاط البحري العماني دورا مهما في توسيع التجاره الخارجيه مع شرق اسيا حيث امتلكت عمان اسطولا بحريا ضخما مكنها من بسط سيطرتها علي الخليج وح', 'يمتد تاريخ عمان الحديث والمعاصر من مملكة النباهنة وحتى يومنا هذا، حيث بدأت مع وصول المستكشفين البرتغاليين إلى الشرق ومن ثم سيطرتهم على الهند والخليج العربي وشرق أفريقيا. كان للنشاط البحري العماني دوراً مهماً في توسيع التجارة الخارجية مع شرق آسيا حيث امتلكت عمان أسطولاً بحرياً ضخماً مكنها من بسط سيطرتها على الخليج وحماية ثغورها ومدنها. كما كانت عمان عرضة للعديد من الغزوات الفارسية والسعودية وخضعت للسيطرة الأوروبية لعدد من القرون.


== مملكة النباهنة ==

حكم بني نبهان عمان مدة 5 قرون وذلك على فترتين الأولى من 1145 م إلى 1462 م والثانية من 1556 م إلى 1626 م 
أما الفترة الأولى: أستمرت أربعمئة عام تقريباً وبدأت بعد وفاة الإمام أبي جابر موسي بن أبي المعالي موسي بن نجاد في عام 1145 م، وانتهت بوفاه سليمان بن سليمان بن مظفر النبهاني 
أما الفترة الثانية: فأستمرت من عام 1556 م إلى 1626 م وتاريخهم غير معروف إلا أن فلاح بن محسن هو من ادخل زراعه المانجو في عمان وحصن بهلا كبره بالحجم العظيم المشهود له اما امور أخرى غير معروفه ولكن من المعتقد أن نظام الإفلاج الحالي الموجود بعمان من زمنهم ويعتقد أنهم هم من طوروه ووضعوه بالصورة التي تناسبت إلى يومناهذا. هم ليسوا حكام أو سلاطين بل كانوا يلقبوا بالملوك.


== السيطرة الفارسية على عمان ==

كانت العلاقة بين عمان وبلاد فارس غير مستقرة بشكل عام، إذ ظل الحكام الفرس على اختلاف سلالاتهم ينظرون إلى عمان على أنها جزء من إمبراطوريتهم ويطالبونها بدفع الضريبة، وبسبب ضعف مملكة النباهنة وانشغالهم بالصراعات الداخلية، أطمع مملكة هرمز الثرية في مد سيطرتها على ساحل عمان المطل على بحر العرب وقد نجحت في بسط سيطرتها على الساحل في حين ظلت ظفار في يد الرسوليون حكام اليمن بعدها آل أمر ظفار إلى السلطنة الجبرية.

كان للدولة الجبرية دور كبير في دعم الإباضيين في الداخل العماني حيث ساندوا تنصيب الإمام عمر بن الخطاب الخروصي سنة 1487 وثم تنصيب الإمام محمد بن إسماعيل سنة 1500. لكن سطلة الإمام الجديد لم تكن شاملة كل التراب العماني الذي توزع بين عدة حكام فيما يشبه دويلات المدن، فالأئمة في قسم من عمان الداخلية والنبهانيون في قسم والجبريون في قسم آخر في حين ظل أكثر الساحل العماني المطل على خليج عمان تحت حكم مملكة هرمز. كان لأجود بن زامل دور كبير في مد نفوذ الإمارة الجبرية إلى عمان وظلت الهيمنة الجبرية على بعض مناطق عمان لحين وصول البرتغاليين إلى المنطقة.
في 1737 رفض سيف بن سلطان اليعربي مبايعة بلعرب للإمامة وطلب من الحكومة الفارسية في عهد نادر شاه أن ترسل له قوات كي يخضغ خصومه. وقد أبحرت القوات الفارسية في 14 مارس 1737 م باتجاه السواحل العمانية بقيادة لطيف خان، ولكن رؤساء القبائل العمانية تمكنوا من الصلح بين سيف بن سلطان وبلعرب بن حمير.
ولكن عاود الفرس غزو عمان عام 1741 م بسبب استنجاد سيف بالفرس مرة أخرى وذلك بعد أن عزله العلماء للمرة الثانية نتيجة سوء سيرته ومخالفة للشريعة الإسلامية، وبايعوا سلطان بن مرشد بالإمامة، وادى هذا الصراع إلى سقوط دولة اليعارية بعد وفاة كل من سلطان ابن مرشد قائد المقاومة العمانية داخل الحصن الرئيسي في صحار، وسيف بن سلطان الثاني في قلعة الحزم بالرستاق.
اتسمت العلاقات الفارسية بالدولة البوسعيدية بالتنافس من أجل الحصول على السيادة البحرية، فمن المعروف إن فارس قد سعت ومن خلال فترات مختلفة من تاريخها نحو تحجيم القوة البحرية العمانية. لقد واجه الأسطول الفارسي في عهد نادر شاه مشاكل عديدة منها اعتماده بالدرجة الأولى على المساعدات الأجنبية في بنائه، وكذلك افتقاره إلى وجود الخبرات المحلية المتمرسة في فنون الملاحة مما دفع بقيادة الفرس إلى الاستعانة بالبحارة العرب لقيادة هذا الأسطول، وبعد وفاة نادر شاه خلفه في الحكم كريم خان زند الذي حاول السير على نهج سلفه نادر شاه التوسعي في منطقة الخليج العربي، ومن هذا المنطلق بعث كريم خان برسالة على الإمام أحمد طالبا منه دفع الجزية السنوية، متعللا بما يدعيه بتبعية عمان إلى فارس، ولكن الإمام أحمد بن سعيد رفض المطالب الفارسية باسلوب رجال السياسة المتمرسين الذين يعرفون كيفية مخاطبة التطلعات الاستعمارية، وذلك برفض المطالب الفارسية جملا وتفصيلا.
وبدء الإمام في التخطيط لاستخدام القوة التي قد يلجأ إليها عدوه وقام بالتحاف مع خصوم الفرس وخاصة الأتراك، وبسبب ضعف منافسي الإمام وموت كريم خان، استطاع الإمام أحمد بن سعيد استعادة مركز عمان القوي في منطقة الخليج العربي، لذلك نفهم من السطور السابقة أن العلاقة ما بين الدولة البوسعيدية وفارس، علاقة عدائية من قبل الفرس الذين كانوا يطمعون في خيرات عمان، خصوصا وأن عمان أصبحت لها في ذلك الوقت قوة بحرية كبيرة


== الغزو البرتغالي ==

غادر أسطول برتغالي لشبونة بتاريخ 6 أبريل سنة 1506 بقيادة ترستاو دا كونها وألفونسو دي البوكيرك، ثم انفصل ألبوكيرك عن «تريستاو» الذي استمر في رحلته إلى الهند، وتوجه البوكيرك ومعه سبع سفن و 500 رجل نحو هرمز في الخليج العربي أحد المراكز التجارية الشرقية الرئيسية. وفي طريقه مر بجزر كوريا موريا فالتقى هناك ب 30 أو 40 مركب صيد قادمة من هرمز ومن الساحل الفارسي، فقام بحرقها. ثم غادرها نحو ميناء قلهات حيث رسا فيها، وأبدى أهلها استعدادهم لدفع الجزية له، وقد تمون الإسطول ثم دفع ثمن المواد التموينية التي حصل عليها. ثم اتجه نحو قريات التي قاومته مقاومة شرسة، ولكن تمكن البرتغاليون من دخولها. وقد لقي 80 من أهلها مصرعهم، في حين خسر البرتغاليون 3 جنود، فدمر البلدة وأحرقها. وأحرق 14 مركبا راسيًا في الميناء، ثم اتجه نحو مسقط فاستقبل وفد من أهالي المدينة أرسلهم الحاكم، حيث ناشدوه بعدم تعريض المدينة لآي تدمير، وأبدوا استعدادهم في الخضوع لملك البرتغال ودفع مايقرره البوكيرك من ضريبة، مثل التي كانوا يدفعونها لملك هرمز. غير أن المفاوضات لم تصل لنتيجة، وأحس البوكيرك بأن الأهالي يستعدون بالخفاء بتنظيم صفوفهم استعدادا للمقاومة والدفاع عن المدينة، فأصدر أمرًا لسفينتين من سفنه بقصف المدينة تمهيدا لشن هجوم عليها. وقد دافع الأهالي بعناد، ولكن مالبث أن اقتحم المدينة وفرض عليها غرامة مالية وقدرها 10 آلاف أشرفي ذهب، على أن تصل إليه ظهر اليوم التالي. فلما عجز الأهالي عن دفعها أمر البوكيرك بإحراق المدينة ومعها مسجدها الكبير والسفن الراسية في الميناء، أما الأسرى من النساء والرجال فقد أخلى سبيلهم بعد جدع أنوفهم وصلم آذانهم. ثم اتجه بعدها نحو صحار فاستولى عليها، ولكن أقر حاكمها في مكانه شريطة الخضوع لحكم الملك عمانويل وأن يدفع الأموال التي كان يدفعها لمملكة هرمز، وكانت 1500 دينار أشرفي. فقد كانت عمان قبل قدوم البرتغاليين تعيش في رخاء من الزراعة والتجارة، إلا أن الغزو البرتغالي قطع تجارتهم وخرب موانئهم التي أخضعها تحت سيطرته وشيد القلاع في الكثير من سواحل خليج عمان والخليج العربي. فقد بنى البرتغاليون في مسقط قلعتي الجلالي والميراني على أنقاض قلاع قديمة. وظلت عمان قابعة تحت الاحتلال الاستعماري البرتغالي الذي كان هدفه احتكار تجارة الشرق وتحويل مساره إلى طريق رأس الرجاء الصالح.

وكتب البوكيرك عن مسقط يقول: 
تمكن الإمام ناصر بن مر', 'يمتد تاريخ عمان الحديث والمعاصر من مملكه النباهنه وحتي يومنا هذا حيث بدات مع وصول المستكشفين البرتغاليين الي الشرق ومن ثم سيطرتهم علي الهند والخليج العربي وشرق افريقيا كان للنشاط البحري العماني دورا مهما في توسيع التجاره الخارجيه مع شرق اسيا حيث امتلكت عمان اسطولا بحريا ضخما مكنها من بسط سيطرتها علي الخليج وحمايه ثغورها ومدنها كما كانت عمان عرضه للعديد من الغزوات الفارسيه والسعوديه وخضعت للسيطره الاوروبيه لعدد من القرون مملكه النباهنه حكم بني نبهان عمان مده 5 قرون وذلك علي فترتين الاولي من 1145 م الي 1462 م والثانيه من 1556 م الي 1626 م اما الفتره الاولي استمرت اربعميه عام تقريبا وبدات بعد وفاه الامام ابي جابر موسي بن ابي المعالي موسي بن نجاد في عام 1145 م وانتهت بوفاه سليمان بن سليمان بن مظفر النبهاني اما الفتره الثانيه فاستمرت من عام 1556 م الي 1626 م وتاريخهم غير معروف الا ان فلاح بن محسن هو من ادخل زراعه المانجو في عمان وحصن بهلا كبره بالحجم العظيم المشهود له اما امور اخري غير معروفه ولكن من المعتقد ان نظام الافلاج الحالي الموجود بعمان من زمنهم ويعتقد انهم هم من طوروه ووضعوه بالصوره التي تناسبت الي يومناهذا هم ليسوا حكام او سلاطين بل كانوا يلقبوا بالملوك السيطره الفارسيه علي عمان كانت العلاقه بين عمان وبلاد فارس غير مستقره بشكل عام اذ ظل الحكام الفرس علي اختلاف سلالاتهم ينظرون الي عمان علي انها جزء من امبراطوريتهم ويطالبونها بدفع الضريبه وبسبب ضعف مملكه النباهنه وانشغالهم بالصراعات الداخليه اطمع مملكه هرمز الثريه في مد سيطرتها علي ساحل عمان المطل علي بحر العرب وقد نجحت في بسط سيطرتها علي الساحل في حين ظلت ظفار في يد الرسوليون حكام اليمن بعدها ال امر ظفار الي السلطنه الجبريه كان للدوله الجبريه دور كبير في دعم الاباضيين في الداخل العماني حيث ساندوا تنصيب الامام عمر بن الخطاب الخروصي سنه 1487 وثم تنصيب الامام محمد بن اسماعيل سنه 1500 لكن سطله الامام الجديد لم تكن شامله كل التراب العماني الذي توزع بين عده حكام فيما يشبه دويلات المدن فالايمه في قسم من عمان الداخليه والنبهانيون في قسم والجبريون في قسم اخر في حين ظل اكثر الساحل العماني المطل علي خليج عمان تحت حكم مملكه هرمز كان لاجود بن زامل دور كبير في مد نفوذ الاماره الجبريه الي عمان وظلت الهيمنه الجبريه علي بعض مناطق عمان لحين وصول البرتغاليين الي المنطقه في 1737 رفض سيف بن سلطان اليعربي مبايعه بلعرب للامامه وطلب من الحكومه الفارسيه في عهد نادر شاه ان ترسل له قوات كي يخضغ خصومه وقد ابحرت القوات الفارسيه في 14 مارس 1737 م باتجاه السواحل العمانيه بقياده لطيف خان ولكن روساء القبايل العمانيه تمكنوا من الصلح بين سيف بن سلطان وبلعرب بن حمير ولكن عاود الفرس غزو عمان عام 1741 م بسبب استنجاد سيف بالفرس مره اخري وذلك بعد ان عزله العلماء للمره الثانيه نتيجه سوء سيرته ومخالفه للشريعه الاسلاميه وبايعوا سلطان بن مرشد بالامامه وادي هذا الصراع الي سقوط دوله اليعاريه بعد وفاه كل من سلطان ابن مرشد قايد المقاومه العمانيه داخل الحصن الرييسي في صحار وسيف بن سلطان الثاني في قلعه الحزم بالرستاق اتسمت العلاقات الفارسيه بالدوله البوسعيديه بالتنافس من اجل الحصول علي السياده البحريه فمن المعروف ان فارس قد سعت ومن خلال فترات مختلفه من تاريخها نحو تحجيم القوه البحريه العمانيه لقد واجه الاسطول الفارسي في عهد نادر شاه مشاكل عديده منها اعتماده بالدرجه الاولي علي المساعدات الاجنبيه في بنايه وكذلك افتقاره الي وجود الخبرات المحليه المتمرسه في فنون الملاحه مما دفع بقياده الفرس الي الاستعانه بالبحاره العرب لقياده هذا الاسطول وبعد وفاه نادر شاه خلفه في الحكم كريم خان زند الذي حاول السير علي نهج سلفه نادر شاه التوسعي في منطقه الخليج العربي ومن هذا المنطلق بعث كريم خان برساله علي الامام احمد طالبا منه دفع الجزيه السنويه متعللا بما يدعيه بتبعيه عمان الي فارس ولكن الامام احمد بن سعيد رفض المطالب الفارسيه باسلوب رجال السياسه المتمرسين الذين يعرفون كيفيه مخاطبه التطلعات الاستعماريه وذلك برفض المطالب الفارسيه جملا وتفصيلا وبدء الامام في التخطيط لاستخدام القوه التي قد يلجا اليها عدوه وقام بالتحاف مع خصوم الفرس وخاصه الاتراك وبسبب ضعف منافسي الامام وموت كريم خان استطاع الامام احمد بن سعيد استعاده مركز عمان القوي في منطقه الخليج العربي لذلك نفهم من السطور السابقه ان العلاقه ما بين الدوله البوسعيديه وفارس علاقه عداييه من قبل الفرس الذين كانوا يطمعون في خيرات عمان خصوصا وان عمان اصبحت لها في ذلك الوقت قوه بحريه كبيره الغزو البرتغالي غادر اسطول برتغالي لشبونه بتاريخ 6 ابريل سنه 1506 بقياده ترستاو دا كونها والفونسو دي البوكيرك ثم انفصل البوكيرك عن تريستاو الذي استمر في رحلته الي الهند وتوجه البوكيرك ومعه سبع سفن و 500 رجل نحو هرمز في الخليج العربي احد المراكز التجاريه الشرقيه الرييسيه وفي طريقه مر بجزر كوريا موريا فالتقي هناك ب 30 او 40 مركب صيد قادمه من هرمز ومن الساحل الفارسي فقام بحرقها ثم غادرها نحو ميناء قلهات حيث رسا فيها وابدي اهلها استعدادهم لدفع الجزيه له وقد تمون الاسطول ثم دفع ثمن المواد التموينيه التي حصل عليها ثم اتجه نحو قريات التي قاومته مقاومه شرسه ولكن تمكن البرتغاليون من دخولها وقد لقي 80 من اهلها مصرعهم في حين خسر البرتغاليون 3 جنود فدمر البلده واحرقها واحرق 14 مركبا راسيا في الميناء ثم اتجه نحو مسقط فاستقبل وفد من اهالي المدينه ارسلهم الحاكم حيث ناشدوه بعدم تعريض المدينه لاي تدمير وابدوا استعدادهم في الخضوع لملك البرتغال ودفع مايقرره البوكيرك من ضريبه مثل التي كانوا يدفعونها لملك هرمز غير ان المفاوضات لم تصل لنتيجه واحس البوكيرك بان الاهالي يستعدون بالخفاء بتنظيم صفوفهم استعدادا للمقاومه والدفاع عن المدينه فاصدر امرا لسفينتين من سفنه بقصف المدينه تمهيدا لشن هجوم عليها وقد دافع الاهالي بعناد ولكن مالبث ان اقتحم المدينه وفرض عليها غرامه ماليه وقدرها 10 الاف اشرفي ذهب علي ان تصل اليه ظهر اليوم التالي فلما عجز الاهالي عن دفعها امر البوكيرك باحراق المدينه ومعها مسجدها الكبير والسفن الراسيه في الميناء اما الاسري من النساء والرجال فقد اخلي سبيلهم بعد جدع انوفهم وصلم اذانهم ثم اتجه بعدها نحو صحار فاستولي عليها ولكن اقر حاكمها في مكانه شريطه الخضوع لحكم الملك عمانويل وان يدفع الاموال التي كان يدفعها لمملكه هرمز وكانت 1500 دينار اشرفي فقد كانت عمان قبل قدوم البرتغاليين تعيش في رخاء من الزراعه والتجاره الا ان الغزو البرتغالي قطع تجارتهم وخرب موانيهم التي اخضعها تحت سيطرته وشيد القلاع في الكثير من سواحل خليج عمان والخليج العربي فقد بني البرتغاليون في مسقط قلعتي الجلالي والميراني علي انقاض قلاع قديمه وظلت عمان قابعه تحت الاحتلال الاستعماري البرتغالي الذي كان هدفه احتكار تجاره الشرق وتحويل مساره الي طريق راس الرجاء الصالح وكتب البوكيرك عن مسقط يقول تمكن الامام ناصر بن مر', 'cat-05-castles-forts', 'القلاع والحصون التاريخية', 'vol-01', '["قلعة","حصن","بهلا","الجلالي","الميراني","الإمام","أحمد بن سعيد","البوسعيد"]'::jsonb, 'قلعه حصن بهلا الجلالي الميراني الامام احمد بن سعيد البوسعيد', 'الموسوعة الحرة (مرخصة تحت المشاع الإبداعي CC BY-SA 4.0 — مصدر دولي مفتوح)', 'src-79ee3163', 'https://ar.wikipedia.org/wiki/%D8%AA%D8%A7%D8%B1%D9%8A%D8%AE_%D8%B3%D9%84%D8%B7%D9%86%D8%A9_%D8%B9%D9%85%D8%A7%D9%86', '[{"title":"تاريخ سلطنة عمان","url":"https://ar.wikipedia.org/wiki/%D8%AA%D8%A7%D8%B1%D9%8A%D8%AE_%D8%B3%D9%84%D8%B7%D9%86%D8%A9_%D8%B9%D9%85%D8%A7%D9%86","publisher":"الموسوعة الحرة (مرخصة تحت المشاع الإبداعي CC BY-SA 4.0 — مصدر دولي مفتوح)","accessDate":"2026-10-16","sourceType":"international"}]'::jsonb, '2026-10-12', '2026-10-16', 'published', 'confirmed_fact', 'Creative Commons Attribution-ShareAlike 4.0 (CC BY-SA 4.0) مع الإحالة للرابط الأصلي', '[]'::jsonb, '4ffff3b2727f238f226e56f53b8d5da5', 1, '2026-10-16T10:41:13.820Z', '2026-10-16T11:23:07.535Z') ON CONFLICT (id) DO NOTHING;
INSERT INTO articles (id, slug, title, title_normalized, summary, summary_normalized, content, content_normalized, category_id, subcategory, volume_id, keywords, keywords_normalized, author_or_publisher, source_id, source_url, references_list, published_at, last_verified_at, status, fact_classification, license_info, images, content_hash, views_count, created_at, updated_at) VALUES ('art-8566db9732', 'السياحة-في-سلطنة-عمان-9732', 'السياحة في سلطنة عمان', 'السياحه في سلطنه عمان', 'السياحة في سلطنة عمان، تملك سلطنة عمان مقومات سياحية كثيرة بحكم موقعها الوسيط كبوابة بين شرق العالم وغربه، نَمت السياحة في عمان بشكل كبير و ملحوظ خلال العقد الأول من القرن الحادي والعشرين، وفي عام 2019، استقطبت عُمان حوالي 3.5 مليون زائر من جميع أنحاء العالم، بزيادة عن 3.1 مليون في عام 2017 وفقًا لنشرة إحصاءات السيا...', 'السياحه في سلطنه عمان تملك سلطنه عمان مقومات سياحيه كثيره بحكم موقعها الوسيط كبوابه بين شرق العالم وغربه نمت السياحه في عمان بشكل كبير و ملحوظ خلال العقد الاول من القرن الحادي والعشرين وفي عام 2019 استقطبت عمان حوالي 3 5 مليون زاير من جميع انحاء العالم بزياده عن 3 1 مليون في عام 2017 وفقا لنشره احصاءات السيا', 'السياحة في سلطنة عمان، تملك سلطنة عمان مقومات سياحية كثيرة بحكم موقعها الوسيط كبوابة بين شرق العالم وغربه، نَمت السياحة في عمان بشكل كبير و ملحوظ خلال العقد الأول من القرن الحادي والعشرين، وفي عام 2019، استقطبت عُمان حوالي 3.5 مليون زائر من جميع أنحاء العالم، بزيادة عن 3.1 مليون في عام 2017 وفقًا لنشرة إحصاءات السياحة لعام 2019 الصادرة عن المركز الوطني للإحصاء والمعلومات، عمان.
لدى عمان العديد من مناطق الجذب السياحي، لا سيما في مجال السياحة الثقافية. اختيرت مسقط كأفضل مدينة للزيارة من قبل ناشر دليل السفر الأمريكي لونلي بلانيت في عام 2012، واختيرت كعاصمة للسياحة العربية لعام 2012.


== التأشيرة ==
يجب على زوار سلطنة عمان الحصول على تأشيرة قبل السفر ما لم يأتوا من إحدى الدول المعفاة من التأشيرة. حيث يمكن لمواطني الدول الأعضاء في مجلس التعاون الخليجي السفر إلى عمان دون قيود التأشيرة وكذلك يمكن لمواطني 69 دولة أخرى التقدم للحصول على تأشيرة عبر الإنترنت صالحة لمدة 30 يومًا ويجب أن يحمل جميع الزوار جواز سفر صالحًا لمدة 6 أشهر.


== إحصائيات ==
باستثناء دول مجلس التعاون الخليجي، كانت الدول التي لديها أكبر عدد من حاملي جوازات السفر الذين زاروا عمان في عام 2013 هي:


== الأنشطة ==


=== سياحة الرمال ===
تعتبر رمال محافظة الشرقية (بدية - قبضة جعلان )وجهة مفضلة لمحبي سياحة الصحراء والتخييم الصحراوي والتطعيس في الرمال والشوي فوق الرمل.


=== الشواطئ ===
هناك الكثير من الشواطئ الممتدة على طول السلطنة، مثل شاطئ قنتب وشاطئ القرم وغيرها من الشواطئ الرملية البكر حيث يمكن ممارسة السباحة والغطس لمشاهدة الشعاب المرجانية وكذلك يمكن مشاهدة الدلافين ومراقبة الطيور و الأسماك.


== المهرجانات ==


=== مهرجان صلالة السياحي ===

مهرجان صلالة السياحي مهرجان سنوي يقام في صلالة بمحافظة ظفار في سلطنة عمان. يقام كل في فصل الخريف من 15 يوليو إلى 31 أغسطس.


== السياحة التاريخية ==


== المناطق السياحية ==


=== الجبل الأخضر ===

الجبل الأخضر هو جبل يقع في سلطنة عمان في ولاية نزوى، وهو جزء من سلسلة جبال الحجر، ويشتهر الجبل الأخضر بتنوع منتجاته الزراعية كالفاكهة والزهور والرمان والخوخ والمشمش واللوز والجوز والورود ويبلغ ارتفاعه 3000 متر ويتوافد السياح بكثرة على المنطقة وخاصة في أواخر شهر أكتوبر، والذي يزداد فيه تألق منطقة الجبل الأخضر.


=== جبل شمس ===
يقع في ولاية الحمراء بمحافظة الداخليةهو أعلى قمة جبلية في عمان ويرتفع جبل شمس ما يقارب 3500م عن سطح البحر، وهذا الارتفاع ساعد على تغير المناخ عن باقي المناطق بالسلطنة وشبه الجزيرة العربية. حيث تصل درجة الحرارة إلى (0) درجة في فصل الشتاء، وما بين 26 - 35 درجة في فصل الصيف، ما جعله مصدر جذب للسياح الأجانب من هواة التخييم وبعض العائلات العربية التي تنشد الهدوء والطقس البديع، وهذا كما قال فارس الخاطري المدير التنفيذي لمنتجع جبل شمس، وأضاف أن المنتجع يوفر كل طلبات العائلات العربية من الخصوصية وإقامة حفلات الشوي في الهواء الطلق وتوفير البرامج الترفيهية.
لطبيعة الصعود المتعرج للجبل يتيح لك الاطلاع على بعض من جوانب المعالم السياحية الأخرى، ومن أهمها قرية غول القديمة، وهي عبارة عن قرية تظهر مبانيها الطينية على حافة الجبل وأثناء صعودك تشعر بانخفاض درجات الحرارة، حينها ستبدأ بملاحظة كثرة نمو الأشجار البرية التي تتوزع على جانبي الطريق وكذلك في مجاري الأودية التي تنحدر في الفوالق الصخرية.


== وادي دربات ==
يعد وادي دربات صلالة (وادي الدربات) أحد أجمل المواقع ذات المناظر الطبيعية الخلابة لمحبي الطبيعة في محافظة ظفار بسلطنة عُمان. يحاط هذا الوادي الخلاب بالمساحات الخضراء المورقة والشلالات والحياة البرية، ويوفر هذا الوادي الخلاب كل ما تحتاجه لقضاء يوم عائلي لا يُنسى


=== جبل إتين وقبر أيوب ===
يقع جبل إتين في محافظة ظفار على ارتفاع 2000 متر، ومنطقة جبل إتين تعتبر من الأماكن الجميلة للاستجمام وقضاء وقت في ربوع طبيعة محافظة ظفار، وتضم المنطقة أيضاً قبر أيوب، وحجرا أثريا منقوشاً عليه آثار أقدام أيوب.


=== عين أرزات ===
عين أرزات من أهم الأماكن السياحية في محافظة ظفار، خاصة في مدينة صلالة. يزداد عدد زوارها خاصة في فصل الخريف، وهي أكثر عيون المياه غزارة، وهي مصدر للمياه في مزرعة رزات والمزارع الحكومية القريبة من قصر المعمورة. يوجد أمام العين كهف يستهوي الزوار، وتبعد عن مدينة صلالة حوالي 9 كيلومترات تقريبًا.


=== خوروري ===
منطقة يوجد بها خور روري، وأيضا محمية روري الخور. المحمية مدينة قديمة مقابلة للخور، تنتشر قطعان من الماشية والجمال على ضفتي الخور.


=== سمهرم القديمة ===
تقع مدينة سمهرم التاريخية على بعد 40 كيلومترا شرق مدينة صلالة، وبالإضافة إلى المياه الجوفية تستمد المدينة مياهها من الشلالات المتدفقة، سميت سمهرم استناداً إلى النقود والأواني والنقوش المكتشفة، وتضم المنطقة أيضاً متحف سمهرم.


=== كهف الهوتة ===

يعد كهف الهوتة من المزارات السياحة الحديثة نسبياً في السلطنة ويقع في ولاية الحمراء بالمنطقة الداخلية وهو أحد العجائب الطبيعية.


== معرض صور ==


== مراجع ==', 'السياحه في سلطنه عمان تملك سلطنه عمان مقومات سياحيه كثيره بحكم موقعها الوسيط كبوابه بين شرق العالم وغربه نمت السياحه في عمان بشكل كبير و ملحوظ خلال العقد الاول من القرن الحادي والعشرين وفي عام 2019 استقطبت عمان حوالي 3 5 مليون زاير من جميع انحاء العالم بزياده عن 3 1 مليون في عام 2017 وفقا لنشره احصاءات السياحه لعام 2019 الصادره عن المركز الوطني للاحصاء والمعلومات عمان لدي عمان العديد من مناطق الجذب السياحي لا سيما في مجال السياحه الثقافيه اختيرت مسقط كافضل مدينه للزياره من قبل ناشر دليل السفر الامريكي لونلي بلانيت في عام 2012 واختيرت كعاصمه للسياحه العربيه لعام 2012 التاشيره يجب علي زوار سلطنه عمان الحصول علي تاشيره قبل السفر ما لم ياتوا من احدي الدول المعفاه من التاشيره حيث يمكن لمواطني الدول الاعضاء في مجلس التعاون الخليجي السفر الي عمان دون قيود التاشيره وكذلك يمكن لمواطني 69 دوله اخري التقدم للحصول علي تاشيره عبر الانترنت صالحه لمده 30 يوما ويجب ان يحمل جميع الزوار جواز سفر صالحا لمده 6 اشهر احصاييات باستثناء دول مجلس التعاون الخليجي كانت الدول التي لديها اكبر عدد من حاملي جوازات السفر الذين زاروا عمان في عام 2013 هي الانشطه سياحه الرمال تعتبر رمال محافظه الشرقيه بديه قبضه جعلان وجهه مفضله لمحبي سياحه الصحراء والتخييم الصحراوي والتطعيس في الرمال والشوي فوق الرمل الشواطي هناك الكثير من الشواطي الممتده علي طول السلطنه مثل شاطي قنتب وشاطي القرم وغيرها من الشواطي الرمليه البكر حيث يمكن ممارسه السباحه والغطس لمشاهده الشعاب المرجانيه وكذلك يمكن مشاهده الدلافين ومراقبه الطيور و الاسماك المهرجانات مهرجان صلاله السياحي مهرجان صلاله السياحي مهرجان سنوي يقام في صلاله بمحافظه ظفار في سلطنه عمان يقام كل في فصل الخريف من 15 يوليو الي 31 اغسطس السياحه التاريخيه المناطق السياحيه الجبل الاخضر الجبل الاخضر هو جبل يقع في سلطنه عمان في ولايه نزوي وهو جزء من سلسله جبال الحجر ويشتهر الجبل الاخضر بتنوع منتجاته الزراعيه كالفاكهه والزهور والرمان والخوخ والمشمش واللوز والجوز والورود ويبلغ ارتفاعه 3000 متر ويتوافد السياح بكثره علي المنطقه وخاصه في اواخر شهر اكتوبر والذي يزداد فيه تالق منطقه الجبل الاخضر جبل شمس يقع في ولايه الحمراء بمحافظه الداخليههو اعلي قمه جبليه في عمان ويرتفع جبل شمس ما يقارب 3500م عن سطح البحر وهذا الارتفاع ساعد علي تغير المناخ عن باقي المناطق بالسلطنه وشبه الجزيره العربيه حيث تصل درجه الحراره الي 0 درجه في فصل الشتاء وما بين 26 35 درجه في فصل الصيف ما جعله مصدر جذب للسياح الاجانب من هواه التخييم وبعض العايلات العربيه التي تنشد الهدوء والطقس البديع وهذا كما قال فارس الخاطري المدير التنفيذي لمنتجع جبل شمس واضاف ان المنتجع يوفر كل طلبات العايلات العربيه من الخصوصيه واقامه حفلات الشوي في الهواء الطلق وتوفير البرامج الترفيهيه لطبيعه الصعود المتعرج للجبل يتيح لك الاطلاع علي بعض من جوانب المعالم السياحيه الاخري ومن اهمها قريه غول القديمه وهي عباره عن قريه تظهر مبانيها الطينيه علي حافه الجبل واثناء صعودك تشعر بانخفاض درجات الحراره حينها ستبدا بملاحظه كثره نمو الاشجار البريه التي تتوزع علي جانبي الطريق وكذلك في مجاري الاوديه التي تنحدر في الفوالق الصخريه وادي دربات يعد وادي دربات صلاله وادي الدربات احد اجمل المواقع ذات المناظر الطبيعيه الخلابه لمحبي الطبيعه في محافظه ظفار بسلطنه عمان يحاط هذا الوادي الخلاب بالمساحات الخضراء المورقه والشلالات والحياه البريه ويوفر هذا الوادي الخلاب كل ما تحتاجه لقضاء يوم عايلي لا ينسي جبل اتين وقبر ايوب يقع جبل اتين في محافظه ظفار علي ارتفاع 2000 متر ومنطقه جبل اتين تعتبر من الاماكن الجميله للاستجمام وقضاء وقت في ربوع طبيعه محافظه ظفار وتضم المنطقه ايضا قبر ايوب وحجرا اثريا منقوشا عليه اثار اقدام ايوب عين ارزات عين ارزات من اهم الاماكن السياحيه في محافظه ظفار خاصه في مدينه صلاله يزداد عدد زوارها خاصه في فصل الخريف وهي اكثر عيون المياه غزاره وهي مصدر للمياه في مزرعه رزات والمزارع الحكوميه القريبه من قصر المعموره يوجد امام العين كهف يستهوي الزوار وتبعد عن مدينه صلاله حوالي 9 كيلومترات تقريبا خوروري منطقه يوجد بها خور روري وايضا محميه روري الخور المحميه مدينه قديمه مقابله للخور تنتشر قطعان من الماشيه والجمال علي ضفتي الخور سمهرم القديمه تقع مدينه سمهرم التاريخيه علي بعد 40 كيلومترا شرق مدينه صلاله وبالاضافه الي المياه الجوفيه تستمد المدينه مياهها من الشلالات المتدفقه سميت سمهرم استنادا الي النقود والاواني والنقوش المكتشفه وتضم المنطقه ايضا متحف سمهرم كهف الهوته يعد كهف الهوته من المزارات السي